        // ---------- Modulos CS2 ----------
        ["cs2.title"] = ["CS2 modules", "Módulos CS2", "Модули CS2", "CS2-Module", "Modules CS2", "CS2 模块"],
        ["cs2.sub"] = ["Run each module individually. The All mode applies them automatically.", "Ejecución individual de cada módulo. El modo Todo los aplica automáticamente.", "Запуск каждого модуля по отдельности. Режим «Всё» применяет их автоматически.", "Jedes Modul einzeln ausführen. Der Modus „Alles“ wendet sie automatisch an.", "Exécution individuelle de chaque module. Le mode Tout les applique automatiquement.", "可单独运行每个模块。“全部”模式会自动应用它们。"],
        ["cs2.shader.sub"] = ["Compiled CS2 shaders. Steam regenerates them when the game starts. The folder is located automatically in all Steam libraries.", "Shaders compilados de CS2. Steam los regenera al iniciar el juego. La carpeta se localiza automáticamente en todas las bibliotecas de Steam.", "Скомпилированные шейдеры CS2. Steam создаёт их заново при запуске игры. Папка определяется автоматически во всех библиотеках Steam.", "Kompilierte CS2-Shader. Steam erzeugt sie beim Spielstart neu. Der Ordner wird in allen Steam-Bibliotheken automatisch gefunden.", "Shaders compilés de CS2. Steam les régénère au lancement du jeu. Le dossier est localisé automatiquement dans toutes les bibliothèques Steam.", "CS2 已编译的着色器。Steam 会在游戏启动时重新生成。文件夹会在所有 Steam 库中自动定位。"],
        ["cs2.shader.btn"] = ["Delete shader cache", "Borrar shadercache", "Удалить кэш шейдеров", "Shadercache löschen", "Supprimer le cache", "删除着色器缓存"],
        ["cs2.browse"] = ["Choose folder (steamapps\\shadercache\\730)", "Elegir carpeta (steamapps\\shadercache\\730)", "Выбрать папку (steamapps\\shadercache\\730)", "Ordner wählen (steamapps\\shadercache\\730)", "Choisir le dossier (steamapps\\shadercache\\730)", "选择文件夹 (steamapps\\shadercache\\730)"],
        ["cs2.detect"] = ["Detect", "Detectar", "Найти", "Erkennen", "Détecter", "检测"],
        ["cs2.mouse.sub"] = ["Imports the default Windows mouse settings, or the custom .reg file selected in Settings.", "Importa la configuración de ratón predeterminada de Windows o el archivo .reg personalizado seleccionado en Ajustes.", "Импортирует стандартные настройки мыши Windows или файл .reg, выбранный в настройках.", "Importiert die Standard-Mauseinstellungen von Windows oder die in den Einstellungen gewählte .reg-Datei.", "Importe les paramètres de souris par défaut de Windows ou le fichier .reg personnalisé choisi dans Paramètres.", "导入 Windows 默认鼠标设置，或在“设置”中选择的自定义 .reg 文件。"],
        ["cs2.mouse.btn"] = ["Apply raton.reg", "Aplicar raton.reg", "Применить raton.reg", "raton.reg anwenden", "Appliquer raton.reg", "应用 raton.reg"],
        ["cs2.nv.sub"] = ["Silently imports the RNX Performance profile, optimised for CS2, using NVIDIA Profile Inspector. Both are included in the application.", "Importa de forma silenciosa el perfil RNX Performance, optimizado para CS2, mediante NVIDIA Profile Inspector. Ambos se incluyen en la aplicación.", "Тихо импортирует профиль RNX Performance, оптимизированный для CS2, с помощью NVIDIA Profile Inspector. Оба входят в состав приложения.", "Importiert das für CS2 optimierte Profil RNX Performance im Hintergrund mit NVIDIA Profile Inspector. Beides ist in der Anwendung enthalten.", "Importe en silence le profil RNX Performance, optimisé pour CS2, via NVIDIA Profile Inspector. Les deux sont inclus dans l'application.", "通过 NVIDIA Profile Inspector 静默导入为 CS2 优化的 RNX Performance 配置文件。两者均已包含在应用中。"],
        ["cs2.nv.none"] = ["No NVIDIA GPU detected on this computer. This module requires an NVIDIA graphics card.", "No se ha detectado ninguna GPU NVIDIA en este equipo. Este módulo requiere una tarjeta gráfica NVIDIA.", "GPU NVIDIA не обнаружен. Для этого модуля нужна видеокарта NVIDIA.", "Keine NVIDIA-GPU erkannt. Dieses Modul erfordert eine NVIDIA-Grafikkarte.", "Aucun GPU NVIDIA détecté. Ce module nécessite une carte graphique NVIDIA.", "未检测到 NVIDIA GPU。此模块需要 NVIDIA 显卡。"],
        ["cs2.nv.open"] = ["Open Inspector", "Abrir Inspector", "Открыть Inspector", "Inspector öffnen", "Ouvrir Inspector", "打开 Inspector"],
        ["cs2.nv.btn"] = ["Import profile", "Importar perfil", "Импорт профиля", "Profil importieren", "Importer le profil", "导入配置文件"],
        ["sc.title"] = ["Desktop shortcuts", "Accesos directos", "Ярлыки на рабочем столе", "Desktop-Verknüpfungen", "Raccourcis sur le bureau", "桌面快捷方式"],
        ["sc.sub"] = ["Runs a mode directly and closes when finished.", "Ejecuta un modo directamente y se cierra al finalizar.", "Запускает режим напрямую и закрывается по завершении.", "Führt einen Modus direkt aus und schließt sich danach.", "Exécute un mode directement et se ferme à la fin.", "直接运行某个模式，完成后自动关闭。"],
        ["sc.nobackup"] = ["Shortcut without backup", "Acceso directo sin backup", "Ярлык без бэкапа", "Verknüpfung ohne Backup", "Raccourci sans sauvegarde", "不备份的快捷方式"],
        ["sc.name.nobackup"] = ["RNX - Clean without backup", "RNX - Limpiar sin backup", "RNX - Очистка без копии", "RNX - Ohne Sicherung bereinigen", "RNX - Nettoyer sans sauvegarde", "RNX - 不备份清理"],

        // ---------- Servidores de Valve ----------
        ["nav.servers"] = ["Servers", "Servidores", "Серверы", "Server", "Serveurs", "服务器"],
        ["sv.title"] = ["Valve servers", "Servidores de Valve", "Серверы Valve", "Valve-Server", "Serveurs Valve", "Valve 服务器"],
        ["sv.sub"] = ["Block the locations where you do not want to play. CS2 will not connect to blocked locations during matchmaking. Each block is a Windows Firewall rule; the status is read from the firewall.", "Bloquea las ubicaciones en las que no deseas jugar. CS2 no se conectará a las ubicaciones bloqueadas al buscar partida. Cada bloqueo es una regla del Firewall de Windows; el estado se lee del propio firewall.", "Заблокируйте локации, где не хотите играть. CS2 не будет подключаться к ним при поиске матча. Каждая блокировка — правило брандмауэра Windows; состояние считывается из брандмауэра.", "Sperre die Standorte, auf denen du nicht spielen möchtest. CS2 verbindet sich bei der Spielsuche nicht mit gesperrten Standorten. Jede Sperre ist eine Windows-Firewall-Regel; der Status wird aus der Firewall gelesen.", "Bloquez les emplacements sur lesquels vous ne souhaitez pas jouer. CS2 ne s'y connectera pas lors de la recherche de partie. Chaque blocage est une règle du Pare-feu Windows ; l'état est lu depuis le pare-feu.", "屏蔽你不想游玩的地区。匹配时 CS2 不会连接到已屏蔽的地区。每个屏蔽都是一条 Windows 防火墙规则，状态直接从防火墙读取。"],
        ["sv.refresh"] = ["Refresh", "Actualizar", "Обновить", "Aktualisieren", "Actualiser", "刷新"],
