        // ---------- Plan de energia ----------
        ["mod.power"] = ["RNX Performance power plan", "Plan de energía RNX Performance", "План электропитания RNX Performance", "Energiesparplan RNX Performance", "Mode de gestion de l'alimentation RNX Performance", "RNX Performance 电源计划"],
        ["cs2.pw.sub"] = ["Imports and activates the RNX Performance power plan, tuned for maximum performance and minimum latency in games. It is always imported with the same identifier, so it is never duplicated. The All mode applies it automatically.", "Importa y activa el plan de energía RNX Performance, ajustado para obtener el máximo rendimiento y la mínima latencia en juegos. Se importa siempre con el mismo identificador, por lo que no se duplica. El modo Todo lo aplica automáticamente.", "Импортирует и активирует схему питания RNX Performance, настроенную на максимальную производительность и минимальную задержку в играх. Всегда импортируется с одним идентификатором, поэтому не дублируется. Режим «Всё» применяет её автоматически.", "Importiert und aktiviert den Energiesparplan RNX Performance, abgestimmt auf maximale Leistung und minimale Latenz in Spielen. Er wird immer mit derselben Kennung importiert und daher nie dupliziert. Der Modus „Alles“ wendet ihn automatisch an.", "Importe et active le mode d'alimentation RNX Performance, réglé pour des performances maximales et une latence minimale en jeu. Il est toujours importé avec le même identifiant et n'est donc jamais dupliqué. Le mode Tout l'applique automatiquement.", "导入并启用 RNX Performance 电源计划，针对游戏的最高性能和最低延迟进行调整。始终使用相同标识符导入，因此不会重复。“全部”模式会自动应用。"],
        ["cs2.pw.btn"] = ["Activate plan", "Activar plan", "Включить план", "Plan aktivieren", "Activer le mode", "启用计划"],
        ["step.power"] = ["RNX Performance power plan", "Plan de energía RNX Performance", "План электропитания RNX Performance", "Energiesparplan RNX Performance", "Mode d'alimentation RNX Performance", "RNX Performance 电源计划"],
        ["plan.power"] = ["Power plan", "Plan de energía", "План электропитания", "Energiesparplan", "Mode d'alimentation", "电源计划"],
        ["lg.pw.missing"] = ["POWER: RNX_Performance.pow is not included in the application", "ENERGÍA: RNX_Performance.pow no está incluido en la aplicación", "ПИТАНИЕ: RNX_Performance.pow отсутствует в приложении", "ENERGIE: RNX_Performance.pow ist nicht in der Anwendung enthalten", "ALIMENTATION : RNX_Performance.pow n'est pas inclus dans l'application", "电源：应用中未包含 RNX_Performance.pow"],
        ["lg.pw.reimport"] = ["POWER: the bundled plan has changed; reimporting", "ENERGÍA: el plan incluido ha cambiado; se vuelve a importar", "ПИТАНИЕ: встроенная схема изменилась; повторный импорт", "ENERGIE: Der enthaltene Plan wurde geändert; erneuter Import", "ALIMENTATION : le mode inclus a changé ; réimportation", "电源：内置计划已更改，正在重新导入"],
        ["lg.pw.imported"] = ["POWER: RNX Performance plan imported", "ENERGÍA: plan RNX Performance importado", "ПИТАНИЕ: план RNX Performance импортирован", "ENERGIE: Plan RNX Performance importiert", "ÉNERGIE : mode RNX Performance importé", "电源：已导入 RNX Performance 计划"],
        ["lg.pw.importFail"] = ["POWER: importing the plan failed: {0}", "ENERGÍA: no se pudo importar el plan: {0}", "ПИТАНИЕ: не удалось импортировать план: {0}", "ENERGIE: Import des Plans fehlgeschlagen: {0}", "ÉNERGIE : échec de l'import du mode : {0}", "电源：导入计划失败：{0}"],
        ["lg.pw.active"] = ["POWER: {0} plan active", "ENERGÍA: plan {0} activo", "ПИТАНИЕ: план {0} активен", "ENERGIE: Plan {0} aktiv", "ÉNERGIE : mode {0} actif", "电源：{0} 计划已启用"],
        ["lg.pw.activeFail"] = ["POWER: couldn't activate the plan", "ENERGÍA: no se pudo activar el plan", "ПИТАНИЕ: не удалось включить план", "ENERGIE: Plan konnte nicht aktiviert werden", "ÉNERGIE : impossible d'activer le mode", "电源：无法启用计划"],

        ["lg.pw.importFallback"] = ["POWER: Windows rejected the full import ({0}); creating the plan setting by setting", "ENERGÍA: Windows ha rechazado la importación completa ({0}); se crea el plan ajuste a ajuste", "ПИТАНИЕ: Windows отклонила полный импорт ({0}); схема создаётся по отдельным параметрам", "ENERGIE: Windows hat den vollständigen Import abgelehnt ({0}); Plan wird Einstellung für Einstellung erstellt", "ALIMENTATION : Windows a refusé l'import complet ({0}) ; création du mode paramètre par paramètre", "电源：Windows 拒绝完整导入（{0}），改为逐项创建计划"],
        ["lg.pw.built"] = ["POWER: plan built: {0} settings applied, {1} not supported on this PC", "ENERGÍA: plan creado: {0} ajustes aplicados, {1} no admitidos en este PC", "ПИТАНИЕ: план создан: применено {0}, не поддерживается на этом ПК: {1}", "ENERGIE: Plan erstellt: {0} Einstellungen angewendet, {1} auf diesem PC nicht unterstützt", "ÉNERGIE : mode créé : {0} réglages appliqués, {1} non pris en charge sur ce PC", "电源：计划已创建：已应用 {0} 项，{1} 项本机不支持"],
        ["set.reg.export"] = ["Export current mouse settings", "Exportar la configuración actual del ratón", "Экспорт текущих настроек мыши", "Aktuelle Mauseinstellungen exportieren", "Exporter les paramètres actuels de la souris", "导出当前鼠标设置"],
        ["set.reg.export.tip"] = ["Saves the current Windows mouse settings to a .reg file and uses it from now on", "Guarda la configuración actual del ratón de Windows en un archivo .reg y la utiliza a partir de ahora", "Сохраняет текущие настройки мыши Windows в файл .reg и использует его далее", "Speichert die aktuellen Windows-Mauseinstellungen in einer .reg-Datei und verwendet sie ab sofort", "Enregistre les paramètres actuels de la souris Windows dans un fichier .reg et l'utilise désormais", "将当前 Windows 鼠标设置保存为 .reg 文件并从此使用"],
        ["set.reg.exportName"] = ["My mouse", "Mi raton", "Моя мышь", "Meine Maus", "Ma souris", "我的鼠标"],
        ["toast.set.exported"] = ["Mouse settings exported to {0} and in use", "Configuración del ratón exportada a {0} y en uso", "Настройки мыши экспортированы в {0} и используются", "Mauseinstellungen nach {0} exportiert und aktiv", "Paramètres de la souris exportés vers {0} et utilisés", "鼠标设置已导出到 {0} 并已启用"],
        ["toast.set.exportFail"] = ["The mouse settings could not be exported", "No se ha podido exportar la configuración del ratón", "Не удалось экспортировать настройки мыши", "Mauseinstellungen konnten nicht exportiert werden", "Impossible d'exporter les paramètres de la souris", "无法导出鼠标设置"],
        ["lg.mouse.exported"] = ["MOUSE: current settings exported to {0}", "RATÓN: configuración actual exportada a {0}", "МЫШЬ: текущие настройки экспортированы в {0}", "MAUS: aktuelle Einstellungen nach {0} exportiert", "SOURIS : paramètres actuels exportés vers {0}", "鼠标：当前设置已导出到 {0}"],
        ["lg.mouse.exportFail"] = ["MOUSE: could not export to {0}", "RATÓN: no se ha podido exportar a {0}", "МЫШЬ: не удалось экспортировать в {0}", "MAUS: Export nach {0} fehlgeschlagen", "SOURIS : impossible d'exporter vers {0}", "鼠标：无法导出到 {0}"],
        // ---------- 5.1.1: seguridad, estado, programada ----------
        ["step.rp"] = ["Restore point", "Punto de restauración", "Точка восстановления", "Wiederherstellungspunkt", "Point de restauration", "还原点"],
        ["set.safety"] = ["Safety", "Seguridad", "Безопасность", "Sicherheit", "Sécurité", "安全"],
        ["set.rp.title"] = ["Restore point before Full and Everything", "Punto de restauración antes de Completa y Todo", "Точка восстановления перед «Полной» и «Всё»", "Wiederherstellungspunkt vor Vollständig und Alles", "Point de restauration avant Complet et Tout", "在完整和全部模式前创建还原点"],
        ["set.rp.sub"] = ["Creates a Windows restore point first, so that registry, NVIDIA profile and power plan changes can be undone from Windows. Windows allows one every 24 hours; if a recent one exists, it is used.", "Crea previamente un punto de restauración de Windows para poder revertir desde Windows los cambios en el registro, el perfil NVIDIA y el plan de energía. Windows permite uno cada 24 horas; si ya existe uno reciente, se utiliza ese.", "Сначала создаётся точка восстановления Windows, чтобы изменения реестра, профиля NVIDIA и схемы питания можно было отменить средствами Windows. Windows позволяет одну точку в 24 часа; при наличии недавней используется она.", "Erstellt vorher einen Windows-Wiederherstellungspunkt, damit Änderungen an Registrierung, NVIDIA-Profil und Energiesparplan über Windows rückgängig gemacht werden können. Windows erlaubt einen alle 24 Stunden; ist ein aktueller vorhanden, wird dieser verwendet.", "Crée d'abord un point de restauration Windows afin de pouvoir annuler depuis Windows les modifications du registre, du profil NVIDIA et du mode d'alimentation. Windows en autorise un toutes les 24 heures ; s'il en existe un récent, il est utilisé.", "先创建 Windows 还原点，以便从 Windows 撤销对注册表、NVIDIA 配置文件和电源计划的更改。Windows 每 24 小时只允许创建一个；若已有近期还原点，则使用该还原点。"],
        ["lg.rp.ok"] = ["RESTORE: restore point created", "RESTAURACIÓN: punto de restauración creado", "ВОССТАНОВЛЕНИЕ: точка восстановления создана", "WIEDERHERSTELLUNG: Wiederherstellungspunkt erstellt", "RESTAURATION : point de restauration créé", "还原：已创建还原点"],
        ["lg.rp.recent"] = ["RESTORE: Windows already has a restore point from {0} (one every 24 h allowed); using it", "RESTAURACIÓN: Windows ya tiene un punto de restauración del {0} (permite uno cada 24 h); se utiliza ese", "ВОССТАНОВЛЕНИЕ: в Windows уже есть точка от {0} (одна в 24 ч); используется она", "WIEDERHERSTELLUNG: Windows hat bereits einen Punkt vom {0} (einer alle 24 h); dieser wird verwendet", "RESTAURATION : Windows possède déjà un point du {0} (un toutes les 24 h) ; il est utilisé", "还原：Windows 已有 {0} 的还原点（每 24 小时一个），将使用该还原点"],
        ["lg.rp.disabled"] = ["RESTORE: the restore point was not created (code {0}). System Protection is probably disabled on C: (System > System Protection)", "RESTAURACIÓN: no se ha creado el punto de restauración (código {0}). Es probable que la Protección del sistema esté desactivada en C: (Sistema > Protección del sistema)", "ВОССТАНОВЛЕНИЕ: точка не создана (код {0}). Вероятно, защита системы отключена для C: (Система > Защита системы)", "WIEDERHERSTELLUNG: Kein Wiederherstellungspunkt erstellt (Code {0}). Vermutlich ist der Computerschutz für C: deaktiviert (System > Computerschutz)", "RESTAURATION : point non créé (code {0}). La Protection du système est probablement désactivée sur C: (Système > Protection du système)", "还原：未创建还原点（代码 {0}）。C: 的系统保护可能已关闭（系统 > 系统保护）"],
        ["lg.rp.fail"] = ["RESTORE: couldn't create the restore point: {0}", "RESTAURACIÓN: no se pudo crear el punto de restauración: {0}", "ВОССТАНОВЛЕНИЕ: не удалось создать точку: {0}", "WIEDERHERSTELLUNG: Punkt konnte nicht erstellt werden: {0}", "RESTAURATION : impossible de créer le point : {0}", "还原：无法创建还原点：{0}"],
