        ["cs2.undo.title"] = ["Undo changes", "Deshacer cambios", "Отменить изменения", "Änderungen rückgängig machen", "Annuler les modifications", "撤销更改"],
        ["cs2.undo.btn"] = ["Undo", "Deshacer", "Отменить", "Rückgängig", "Annuler", "撤销"],
        ["cs2.undo.saved"] = ["Restores the configuration that existed before RNX applied its settings: {0}.", "Restaura la configuración previa a los ajustes de RNX: {0}.", "Восстанавливает конфигурацию, действовавшую до применения настроек RNX: {0}.", "Stellt die Konfiguration vor den RNX-Einstellungen wieder her: {0}.", "Rétablit la configuration antérieure aux réglages RNX : {0}.", "恢复 RNX 应用设置之前的配置：{0}。"],
        ["cs2.undo.none"] = ["Nothing to undo yet. The previous configuration is saved here the first time RNX changes the mouse, NVIDIA profile, power plan, network or OEM information.", "No hay cambios que deshacer. La configuración previa se guarda aquí la primera vez que RNX modifica el ratón, el perfil NVIDIA, el plan de energía, la red o la información OEM.", "Отменять пока нечего. Предыдущая конфигурация сохраняется здесь, когда RNX впервые изменяет мышь, профиль NVIDIA, схему питания, сеть или сведения OEM.", "Noch nichts rückgängig zu machen. Die vorherige Konfiguration wird hier gespeichert, sobald RNX erstmals Maus, NVIDIA-Profil, Energiesparplan, Netzwerk oder OEM-Informationen ändert.", "Rien à annuler pour l'instant. La configuration précédente est enregistrée ici la première fois que RNX modifie la souris, le profil NVIDIA, le mode d'alimentation, le réseau ou les informations OEM.", "暂无可撤销的更改。RNX 首次修改鼠标、NVIDIA 配置文件、电源计划、网络或 OEM 信息时，之前的配置会保存在此处。"],
        ["undo.part.mouse"] = ["previous mouse settings", "configuración de ratón anterior", "прежние настройки мыши", "vorherige Mauseinstellungen", "paramètres de souris précédents", "之前的鼠标设置"],
        ["undo.part.power"] = ["power plan {0}", "plan de energía {0}", "план электропитания {0}", "Energiesparplan {0}", "mode d'alimentation {0}", "电源计划 {0}"],
        ["toast.undo.ok"] = ["Previous settings restored", "Ajustes anteriores restaurados", "Прежние настройки восстановлены", "Vorherige Einstellungen wiederhergestellt", "Réglages précédents restaurés", "已恢复之前的设置"],
        ["toast.undo.fail"] = ["Some settings could not be restored. See the Log.", "Algunos ajustes no se han podido restaurar. Consulta el Registro.", "Некоторые настройки не удалось восстановить. См. журнал.", "Einige Einstellungen konnten nicht wiederhergestellt werden. Siehe Protokoll.", "Certains paramètres n'ont pas pu être rétablis. Consultez le Journal.", "部分设置无法恢复。请查看日志。"],
        ["lg.undo.savedMouse"] = ["UNDO: current mouse settings saved", "DESHACER: configuración de ratón actual guardada", "ОТМЕНА: текущие настройки мыши сохранены", "RÜCKGÄNGIG: aktuelle Mauseinstellungen gespeichert", "ANNULER : paramètres de souris actuels enregistrés", "撤销：已保存当前鼠标设置"],
        ["lg.undo.savedPower"] = ["UNDO: current power plan saved ({0})", "DESHACER: plan de energía actual guardado ({0})", "ОТМЕНА: текущая схема питания сохранена ({0})", "RÜCKGÄNGIG: aktueller Energiesparplan gespeichert ({0})", "ANNULER : mode d'alimentation actuel enregistré ({0})", "撤销：已保存当前电源计划（{0}）"],
        ["lg.undo.mouse"] = ["UNDO: previous mouse settings restored", "DESHACER: configuración de ratón anterior restaurada", "ОТМЕНА: прежние настройки мыши восстановлены", "RÜCKGÄNGIG: vorherige Mauseinstellungen wiederhergestellt", "ANNULER : réglages de souris précédents restaurés", "撤销：已恢复之前的鼠标设置"],
        ["lg.undo.power"] = ["UNDO: power plan {0} active again", "DESHACER: plan de energía {0} activo de nuevo", "ОТМЕНА: схема питания {0} снова активна", "RÜCKGÄNGIG: Energiesparplan {0} wieder aktiv", "ANNULER : mode d'alimentation {0} de nouveau actif", "撤销：电源计划 {0} 已重新启用"],
        ["lg.undo.fail"] = ["UNDO: error: {0}", "DESHACER: error: {0}", "ОТМЕНА: ошибка: {0}", "RÜCKGÄNGIG: Fehler: {0}", "ANNULER : erreur : {0}", "撤销：错误：{0}"],
        ["set.sch"] = ["Scheduled cleanup", "Limpieza programada", "Плановая очистка", "Geplante Bereinigung", "Nettoyage planifié", "计划清理"],
        ["set.sch.sub"] = ["Runs automatically through Windows Task Scheduler, minimised and without prompts, with a notification when finished. Daily and weekly cleanups start at 12:00 (weekly on Sundays); if the computer is off, they run as soon as it is turned on. It does not run while CS2 is open.", "Se ejecuta automáticamente mediante el Programador de tareas de Windows, minimizada y sin confirmaciones, con una notificación al finalizar. Las limpiezas diaria y semanal se inician a las 12:00 (la semanal, los domingos); si el equipo está apagado, se ejecutan al encenderlo. No se ejecuta con CS2 abierto.", "Запускается автоматически через Планировщик заданий Windows — в свёрнутом виде, без запросов, с уведомлением по завершении. Ежедневная и еженедельная очистка запускаются в 12:00 (еженедельная — по воскресеньям); если ПК выключен, они выполнятся при включении. Не запускается, пока открыт CS2.", "Läuft automatisch über die Windows-Aufgabenplanung, minimiert und ohne Rückfragen, mit einer Benachrichtigung am Ende. Tägliche und wöchentliche Bereinigungen starten um 12:00 Uhr (wöchentlich sonntags); ist der PC aus, laufen sie beim Einschalten. Läuft nicht, während CS2 geöffnet ist.", "S'exécute automatiquement via le Planificateur de tâches Windows, réduit et sans confirmation, avec une notification à la fin. Les nettoyages quotidien et hebdomadaire démarrent à 12:00 (hebdomadaire le dimanche) ; si l'ordinateur est éteint, ils s'exécutent à son démarrage. Ne s'exécute pas lorsque CS2 est ouvert.", "通过 Windows 任务计划程序自动运行，最小化且无需确认，完成后发送通知。每日和每周清理在 12:00 开始（每周清理在周日）；若电脑关机，则在开机后运行。CS2 运行时不会执行。"],
        ["set.sch.freq"] = ["Frequency", "Frecuencia", "Частота", "Häufigkeit", "Fréquence", "频率"],
        ["set.sch.mode"] = ["Mode", "Modo", "Режим", "Modus", "Mode", "模式"],
