        ["custom.fixes"] = ["Repairs (manual only, not included in All)", "Reparaciones (solo de forma manual, no incluidas en Todo)", "Исправления (только вручную, не входят в «Всё»)", "Reparaturen (nur manuell, nicht in „Alles“ enthalten)", "Réparations (manuelles uniquement, non incluses dans Tout)", "修复（仅手动执行，不包含在“全部”中）"],
        ["fix.store.title"] = ["Fix Microsoft Store (AtlasOS)", "Arreglar Microsoft Store (AtlasOS)", "Исправить Microsoft Store (AtlasOS)", "Microsoft Store reparieren (AtlasOS)", "Réparer le Microsoft Store (AtlasOS)", "修复 Microsoft Store（AtlasOS）"],
        ["fix.store.sub"] = ["AtlasOS fix for when Microsoft Store or apps fail to install or update: rebuilds the app deployment database and removes Gaming Services if installed. Requires a restart.", "Corrección de AtlasOS para cuando Microsoft Store o las aplicaciones no se instalan ni se actualizan: regenera la base de datos de despliegue de aplicaciones y desinstala Gaming Services si está instalado. Requiere reiniciar.", "Исправление AtlasOS на случай, если Microsoft Store или приложения не устанавливаются и не обновляются: пересоздаёт базу развёртывания приложений и удаляет Gaming Services, если они установлены. Требуется перезагрузка.", "AtlasOS-Korrektur, wenn Microsoft Store oder Apps sich nicht installieren oder aktualisieren lassen: erstellt die App-Bereitstellungsdatenbank neu und entfernt Gaming Services, falls installiert. Neustart erforderlich.", "Correctif AtlasOS lorsque Microsoft Store ou les applications ne s'installent ou ne se mettent pas à jour : reconstruit la base de déploiement des applications et supprime Gaming Services s'il est installé. Redémarrage requis.", "AtlasOS 修复方案，适用于 Microsoft Store 或应用无法安装或更新的情况：重建应用部署数据库，并在已安装时移除 Gaming Services。需要重启。"],
        ["fix.store.btn"] = ["Run fix", "Ejecutar arreglo", "Запустить исправление", "Reparatur starten", "Lancer le correctif", "运行修复"],
        ["fix.store.notAtlas"] = ["AtlasOS only (RunAsTI.cmd not found)", "Exclusivo de AtlasOS (no se encuentra RunAsTI.cmd)", "Только для AtlasOS (RunAsTI.cmd не найден)", "Nur für AtlasOS (RunAsTI.cmd nicht gefunden)", "Réservé à AtlasOS (RunAsTI.cmd introuvable)", "仅适用于 AtlasOS（未找到 RunAsTI.cmd）"],
        ["dlg.fix.t"] = ["Run the Microsoft Store fix?", "¿Ejecutar el arreglo de Microsoft Store?", "Запустить исправление Microsoft Store?", "Microsoft-Store-Reparatur starten?", "Lancer le correctif du Microsoft Store ?", "运行 Microsoft Store 修复？"],
        ["dlg.fix.x"] = ["Stops the Store and app services, deletes the app deployment database (StateRepository-Deployment.srd) so that Windows rebuilds it, and uninstalls Gaming Services if installed. A window will show the progress. Restart the computer when it finishes.", "Detiene los servicios de Microsoft Store y de las aplicaciones, elimina la base de datos de despliegue (StateRepository-Deployment.srd) para que Windows la regenere y desinstala Gaming Services si está instalado. El progreso se mostrará en una ventana. Al finalizar, reinicia el equipo.", "Останавливает службы Store и приложений, удаляет базу развёртывания (StateRepository-Deployment.srd), чтобы Windows создала её заново, и удаляет Gaming Services, если они установлены. Ход выполнения отображается в окне. По завершении перезагрузите компьютер.", "Beendet die Store- und App-Dienste, löscht die Bereitstellungsdatenbank (StateRepository-Deployment.srd), damit Windows sie neu erstellt, und deinstalliert Gaming Services, falls vorhanden. Ein Fenster zeigt den Fortschritt. Danach den Computer neu starten.", "Arrête les services du Store et des applications, supprime la base de déploiement (StateRepository-Deployment.srd) pour que Windows la reconstruise et désinstalle Gaming Services s'il est installé. Une fenêtre affiche la progression. Redémarrez l'ordinateur à la fin.", "停止 Store 和应用服务，删除应用部署数据库（StateRepository-Deployment.srd）以便 Windows 重建，并在已安装时卸载 Gaming Services。进度将显示在窗口中。完成后请重启电脑。"],
        ["toast.fix.store"] = ["Microsoft Store repair running in a separate window", "Reparación de Microsoft Store en curso en una ventana independiente", "Восстановление Microsoft Store выполняется в отдельном окне", "Microsoft-Store-Reparatur läuft in einem separaten Fenster", "Réparation de Microsoft Store en cours dans une fenêtre distincte", "Microsoft Store 修复正在单独窗口中运行"],
        ["lg.fix.store"] = ["STORE FIX: AtlasOS fixStoreIssues.cmd started", "REPARACIÓN STORE: iniciado fixStoreIssues.cmd de AtlasOS", "ИСПРАВЛЕНИЕ STORE: запущен fixStoreIssues.cmd из AtlasOS", "STORE-REPARATUR: fixStoreIssues.cmd von AtlasOS gestartet", "RÉPARATION STORE : fixStoreIssues.cmd d'AtlasOS lancé", "STORE 修复：已启动 AtlasOS 的 fixStoreIssues.cmd"],
        ["lg.fix.fail"] = ["STORE FIX: could not be started: {0}", "REPARACIÓN STORE: no se ha podido iniciar: {0}", "ИСПРАВЛЕНИЕ STORE: не удалось запустить: {0}", "STORE-REPARATUR: Start fehlgeschlagen: {0}", "RÉPARATION STORE : lancement impossible : {0}", "STORE 修复：无法启动：{0}"],
        ["dev.title"] = ["Disconnected and faulty devices", "Dispositivos desconectados y con errores", "Отключённые и неисправные устройства", "Getrennte und fehlerhafte Geräte", "Périphériques déconnectés et défaillants", "已断开和故障设备"],
        ["dev.sub"] = ["Removes devices that Windows remembers but are no longer connected, and restarts connected devices reporting errors. Drivers are kept: reconnected devices are reinstalled automatically. The list is shown before any change is made.", "Elimina los dispositivos que Windows conserva pero ya no están conectados y reinicia los conectados que presentan errores. Los controladores se conservan: al volver a conectar un dispositivo, se reinstala automáticamente. La lista se muestra antes de realizar cambios.", "Удаляет устройства, которые Windows помнит, но которые больше не подключены, и перезапускает подключённые устройства с ошибками. Драйверы сохраняются: при повторном подключении устройство установится автоматически. Перед изменениями отображается список.", "Entfernt Geräte, die Windows gespeichert hat, die aber nicht mehr verbunden sind, und startet verbundene Geräte mit Fehlern neu. Treiber bleiben erhalten: Wieder angeschlossene Geräte werden automatisch installiert. Vor jeder Änderung wird die Liste angezeigt.", "Supprime les périphériques mémorisés par Windows qui ne sont plus connectés et redémarre les périphériques connectés en erreur. Les pilotes sont conservés : un périphérique reconnecté est réinstallé automatiquement. La liste est affichée avant toute modification.", "移除 Windows 记录但已不再连接的设备，并重启出错的已连接设备。驱动程序会保留：重新连接的设备将自动重新安装。执行更改前会先显示列表。"],
        ["dev.btn"] = ["Scan…", "Analizar…", "Проверить…", "Prüfen…", "Analyser…", "扫描…"],
        ["dev.scanning"] = ["Scanning for disconnected and faulty devices…", "Buscando dispositivos desconectados y con errores…", "Поиск отключённых и неисправных устройств…", "Suche nach getrennten und fehlerhaften Geräten…", "Recherche des périphériques déconnectés et défaillants…", "正在扫描已断开和故障设备…"],
        ["dev.none"] = ["No disconnected or faulty devices found", "No se han encontrado dispositivos desconectados ni con errores", "Отключённых и неисправных устройств не найдено", "Keine getrennten oder fehlerhaften Geräte gefunden", "Aucun périphérique déconnecté ou défaillant", "未发现已断开或故障设备"],
        ["dev.errorsHeader"] = ["Connected with errors, will be restarted ({0})", "Conectados con errores, se reiniciarán ({0})", "Подключены с ошибками, будут перезапущены ({0})", "Verbunden mit Fehlern, werden neu gestartet ({0})", "Connectés en erreur, seront redémarrés ({0})", "已连接但出错，将重启（{0}）"],
        ["dev.dlg.t"] = ["Remove {0} disconnected devices and restart {1} faulty ones?", "¿Eliminar {0} dispositivos desconectados y reiniciar {1} con errores?", "Удалить {0} отключённых устройств и перезапустить {1} неисправных?", "{0} getrennte Geräte entfernen und {1} fehlerhafte neu starten?", "Supprimer {0} périphériques déconnectés et redémarrer {1} en erreur ?", "移除 {0} 个已断开设备并重启 {1} 个故障设备？"],
        ["dev.dlg.x"] = ["Devices that are currently unplugged are also considered disconnected: their entry is removed and they are reinstalled when reconnected, but their saved settings are lost (volume or audio enhancements, COM port number). A restore point is created first if enabled in Settings.", "Los dispositivos desenchufados en este momento también se consideran desconectados: se elimina su entrada y se reinstalan al volver a conectarlos, pero se pierden sus ajustes guardados (volumen o mejoras de audio, número de puerto COM). Si está activado en Ajustes, antes se crea un punto de restauración.", "Отключённые сейчас устройства тоже считаются отсутствующими: их запись удаляется, при подключении они устанавливаются заново, но сохранённые настройки теряются (громкость, улучшения звука, номер COM-порта). Если включено в настройках, сначала создаётся точка восстановления.", "Derzeit ausgesteckte Geräte gelten ebenfalls als getrennt: Ihr Eintrag wird entfernt und beim erneuten Anschließen neu installiert, gespeicherte Einstellungen gehen jedoch verloren (Lautstärke, Audioverbesserungen, COM-Portnummer). Falls in den Einstellungen aktiviert, wird zuvor ein Wiederherstellungspunkt erstellt.", "Les périphériques actuellement débranchés sont aussi considérés comme déconnectés : leur entrée est supprimée et ils sont réinstallés à la reconnexion, mais leurs paramètres enregistrés sont perdus (volume, améliorations audio, numéro de port COM). Un point de restauration est créé au préalable s'il est activé dans Paramètres.", "当前已拔出的设备也会被视为已断开：其条目将被移除，重新连接时会重新安装，但已保存的设置会丢失（音量或音效增强、COM 端口号）。若在“设置”中启用，将先创建还原点。"],
        ["dev.dlg.yes"] = ["Remove and repair", "Eliminar y reparar", "Удалить и исправить", "Entfernen und reparieren", "Supprimer et réparer", "移除并修复"],
        ["dev.toast"] = ["{0} disconnected devices removed, {1} repaired", "{0} dispositivos desconectados eliminados, {1} reparados", "Удалено отключённых устройств: {0}, исправлено: {1}", "{0} getrennte Geräte entfernt, {1} repariert", "{0} périphériques déconnectés supprimés, {1} réparés", "已移除 {0} 个已断开设备，修复 {1} 个"],
        ["dev.toast.failed"] = ["{0} could not be removed", "{0} no se han podido eliminar", "Не удалось удалить: {0}", "{0} konnten nicht entfernt werden", "{0} n'ont pas pu être supprimés", "{0} 个无法移除"],
        ["lg.dev.removed"] = ["DEVICES: removed {0} ({1})", "DISPOSITIVOS: eliminado {0} ({1})", "УСТРОЙСТВА: удалено {0} ({1})", "GERÄTE: {0} entfernt ({1})", "PÉRIPHÉRIQUES : {0} supprimé ({1})", "设备：已移除 {0}（{1}）"],
        ["lg.dev.removeFail"] = ["DEVICES: could not remove {0} (code {1})", "DISPOSITIVOS: no se ha podido eliminar {0} (código {1})", "УСТРОЙСТВА: не удалось удалить {0} (код {1})", "GERÄTE: {0} konnte nicht entfernt werden (Code {1})", "PÉRIPHÉRIQUES : impossible de supprimer {0} (code {1})", "设备：无法移除 {0}（代码 {1}）"],
        ["lg.dev.fixed"] = ["DEVICES: {0} is working again", "DISPOSITIVOS: {0} vuelve a funcionar correctamente", "УСТРОЙСТВА: {0} снова работает", "GERÄTE: {0} funktioniert wieder", "PÉRIPHÉRIQUES : {0} fonctionne de nouveau", "设备：{0} 已恢复正常"],
        ["lg.dev.stillError"] = ["DEVICES: {0} still reports an error (its driver may need to be reinstalled)", "DISPOSITIVOS: {0} sigue con errores (puede requerir reinstalar su controlador)", "УСТРОЙСТВА: {0} по-прежнему с ошибкой (может потребоваться переустановка драйвера)", "GERÄTE: {0} meldet weiterhin einen Fehler (Treiber muss ggf. neu installiert werden)", "PÉRIPHÉRIQUES : {0} est toujours en erreur (son pilote doit peut-être être réinstallé)", "设备：{0} 仍有错误（可能需要重新安装驱动程序）"],
        ["lg.dev.done"] = ["DEVICES: {0} disconnected removed, {1} failed, {2} repaired", "DISPOSITIVOS: {0} desconectados eliminados, {1} con fallo, {2} reparados", "УСТРОЙСТВА: удалено {0}, ошибок {1}, исправлено {2}", "GERÄTE: {0} entfernt, {1} fehlgeschlagen, {2} repariert", "PÉRIPHÉRIQUES : {0} supprimés, {1} en échec, {2} réparés", "设备：已移除 {0} 个，失败 {1} 个，修复 {2} 个"],
        ["lg.dev.fail"] = ["DEVICES: error: {0}", "DISPOSITIVOS: error: {0}", "УСТРОЙСТВА: ошибка: {0}", "GERÄTE: Fehler: {0}", "PÉRIPHÉRIQUES : erreur : {0}", "设备：错误：{0}"],
        // ---------- 5.3.0: activacion ----------
        ["act.title"] = ["Activation", "Activación", "Активация", "Aktivierung", "Activation", "激活"],
        ["act.sub"] = ["Enter the 6-digit activation code to use RNX Cache Cleaner on this computer. Each code is valid for one minute and only needs to be entered once.", "Introduce el código de activación de 6 dígitos para usar RNX Cache Cleaner en este equipo. Cada código es válido durante un minuto y solo hay que introducirlo una vez.", "Введите 6-значный код активации, чтобы использовать RNX Cache Cleaner на этом компьютере. Каждый код действует одну минуту и вводится только один раз.", "Gib den 6-stelligen Aktivierungscode ein, um RNX Cache Cleaner auf diesem Computer zu verwenden. Jeder Code ist eine Minute gültig und muss nur einmal eingegeben werden.", "Saisissez le code d'activation à 6 chiffres pour utiliser RNX Cache Cleaner sur cet ordinateur. Chaque code est valable une minute et ne doit être saisi qu'une seule fois.", "输入 6 位激活码即可在此电脑上使用 RNX Cache Cleaner。每个代码有效期为一分钟，只需输入一次。"],
        ["act.btn"] = ["Activate", "Activar", "Активировать", "Aktivieren", "Activer", "激活"],
        ["act.ok"] = ["Activation completed.", "Activación completada.", "Активация выполнена.", "Aktivierung abgeschlossen.", "Activation terminée.", "激活完成。"],
        ["act.wrong"] = ["Invalid or expired code. Request a new code and enter it within one minute.", "Código no válido o caducado. Solicita un código nuevo e introdúcelo en menos de un minuto.", "Неверный или просроченный код. Запросите новый код и введите его в течение минуты.", "Ungültiger oder abgelaufener Code. Neuen Code anfordern und innerhalb einer Minute eingeben.", "Code invalide ou expiré. Demandez un nouveau code et saisissez-le en moins d'une minute.", "代码无效或已过期。请索取新代码并在一分钟内输入。"],
        ["act.locked"] = ["Too many failed attempts. Try again in {0} s.", "Demasiados intentos fallidos. Vuelve a intentarlo en {0} s.", "Слишком много неудачных попыток. Повторите через {0} с.", "Zu viele Fehlversuche. Erneut versuchen in {0} s.", "Trop de tentatives échouées. Réessayez dans {0} s.", "失败次数过多。请在 {0} 秒后重试。"],
        ["act.unavailable"] = ["This build does not include activation support. Download the official version from GitHub.", "Esta compilación no incluye la activación. Descarga la versión oficial desde GitHub.", "Эта сборка не поддерживает активацию. Скачайте официальную версию с GitHub.", "Dieser Build unterstützt keine Aktivierung. Offizielle Version von GitHub herunterladen.", "Cette version ne prend pas en charge l'activation. Téléchargez la version officielle sur GitHub.", "此版本不支持激活。请从 GitHub 下载官方版本。"],
        ["act.contact"] = ["Contact", "Contacto", "Контакты", "Kontakt", "Contact", "联系方式"],
        ["act.contact.x"] = ["To obtain an activation code, contact the administrator:", "Para obtener un código de activación, contacta con el administrador:", "Чтобы получить код активации, свяжитесь с администратором:", "Für einen Aktivierungscode an den Administrator wenden:", "Pour obtenir un code d'activation, contactez l'administrateur :", "如需获取激活码，请联系管理员："],
        ["act.mail"] = ["Email", "Correo", "Почта", "E-Mail", "E-mail", "邮箱"],

        // ---------- 5.3.0: Windows (ajustes, apps, inicio, tareas) ----------
        ["nav.win.tweaks"] = ["Optimisation", "Optimización", "Оптимизация", "Optimierung", "Optimisation", "优化"],
        ["nav.win.apps"] = ["Apps", "Apps", "Приложения", "Apps", "Applications", "应用"],
        ["nav.win.startup"] = ["Startup", "Inicio", "Автозагрузка", "Autostart", "Démarrage", "启动项"],
        ["nav.win.tasks"] = ["Tasks", "Tareas", "Задания", "Aufgaben", "Tâches", "任务"],
        ["ws.tweaks.title"] = ["Windows optimisation", "Optimización de Windows", "Оптимизация Windows", "Windows-Optimierung", "Optimisation de Windows", "Windows 优化"],
        ["ws.tweaks.sub"] = ["Performance, privacy and system settings, each with its risk level. The current state is read from the system, and every setting applied from RNX can be undone.", "Ajustes de rendimiento, privacidad y sistema, cada uno con su nivel de riesgo. El estado se lee del propio sistema y cada ajuste aplicado desde RNX puede deshacerse.", "Параметры производительности, конфиденциальности и системы с уровнем риска. Состояние считывается из системы, любой параметр, применённый из RNX, можно отменить.", "Leistungs-, Datenschutz- und Systemeinstellungen, jeweils mit Risikostufe. Der Status wird aus dem System gelesen; jede über RNX angewendete Einstellung kann rückgängig gemacht werden.", "Réglages de performances, de confidentialité et du système, chacun avec son niveau de risque. L'état est lu depuis le système et chaque réglage appliqué depuis RNX peut être annulé.", "性能、隐私和系统设置，均标有风险等级。状态直接从系统读取，通过 RNX 应用的每项设置都可撤销。"],
        ["ws.apps.title"] = ["Preinstalled apps", "Apps preinstaladas", "Предустановленные приложения", "Vorinstallierte Apps", "Applications préinstallées", "预装应用"],
        ["ws.apps.sub"] = ["Microsoft Store apps installed for this user, classified by how safe they are to remove.", "Apps de Microsoft Store instaladas para este usuario, clasificadas según lo seguro que es quitarlas.", "Приложения Microsoft Store этого пользователя, классифицированные по безопасности удаления.", "Für diesen Benutzer installierte Microsoft-Store-Apps, eingestuft danach, wie sicher sie sich entfernen lassen.", "Applications Microsoft Store installées pour cet utilisateur, classées selon la sûreté de leur suppression.", "为当前用户安装的 Microsoft Store 应用，按移除的安全程度分类。"],
        ["ws.startup.title"] = ["Startup programs", "Programas de inicio", "Программы автозагрузки", "Autostart-Programme", "Programmes au démarrage", "启动程序"],
        ["ws.startup.sub"] = ["Programs that start with Windows. Disabling one does not uninstall it and can be reverted at any time, as in Task Manager.", "Programas que se inician con Windows. Desactivar uno no lo desinstala y puede revertirse en cualquier momento, igual que en el Administrador de tareas.", "Программы, запускаемые вместе с Windows. Отключение не удаляет программу и обратимо в любой момент, как в Диспетчере задач.", "Programme, die mit Windows starten. Deaktivieren deinstalliert nichts und ist jederzeit umkehrbar, wie im Task-Manager.", "Programmes lancés avec Windows. Les désactiver ne les désinstalle pas et reste réversible à tout moment, comme dans le Gestionnaire des tâches.", "随 Windows 启动的程序。禁用不会卸载程序，且可随时恢复，与任务管理器相同。"],
        ["ws.tasks.title"] = ["Scheduled tasks", "Tareas programadas", "Запланированные задания", "Geplante Aufgaben", "Tâches planifiées", "计划任务"],
        ["ws.tasks.sub"] = ["Third-party scheduled tasks (updaters, telemetry, launchers). Windows tasks and RNX tasks are not listed and are never modified.", "Tareas programadas de terceros (actualizadores, telemetría, lanzadores). Las tareas de Windows y las de RNX no se muestran y nunca se modifican.", "Запланированные задания сторонних программ (обновления, телеметрия, лаунчеры). Задания Windows и RNX не отображаются и не изменяются.", "Geplante Aufgaben von Drittanbietern (Updater, Telemetrie, Launcher). Windows- und RNX-Aufgaben werden nicht angezeigt und nie verändert.", "Tâches planifiées tierces (mises à jour, télémétrie, lanceurs). Les tâches de Windows et de RNX ne sont pas listées et ne sont jamais modifiées.", "第三方计划任务（更新程序、遥测、启动器）。不会列出也不会修改 Windows 和 RNX 的任务。"],
        ["ws.loading"] = ["Reading the current state…", "Leyendo el estado actual…", "Чтение текущего состояния…", "Aktueller Status wird gelesen…", "Lecture de l'état actuel…", "正在读取当前状态…"],
        ["ws.applySafe"] = ["Apply all safe settings", "Aplicar todos los seguros", "Применить все безопасные", "Alle sicheren anwenden", "Appliquer tous les réglages sûrs", "应用所有安全设置"],
        ["ws.summary"] = ["{0} of {1} settings applied", "{0} de {1} ajustes aplicados", "Применено {0} из {1}", "{0} von {1} Einstellungen angewendet", "{0} réglages appliqués sur {1}", "已应用 {0} / {1} 项设置"],
