        ["ws.cat.privacy"] = ["Privacy and telemetry", "Privacidad y telemetría", "Конфиденциальность и телеметрия", "Datenschutz und Telemetrie", "Confidentialité et télémétrie", "隐私与遥测"],
        ["ws.cat.ai"] = ["Artificial intelligence", "Inteligencia artificial", "Искусственный интеллект", "Künstliche Intelligenz", "Intelligence artificielle", "人工智能"],
