        ["ws.cat.services"] = ["Services", "Servicios", "Службы", "Dienste", "Services", "服务"],
        ["ws.credit"] = ["Selection and risk classification based on optimizerDuck by itsfatduck (GPL-3.0), implemented independently in RNX.", "Selección y clasificación de riesgo basadas en optimizerDuck de itsfatduck (GPL-3.0), implementadas de forma independiente en RNX.", "Подборка и оценка рисков основаны на optimizerDuck от itsfatduck (GPL-3.0), реализованы в RNX самостоятельно.", "Auswahl und Risikoeinstufung basieren auf optimizerDuck von itsfatduck (GPL-3.0), unabhängig in RNX implementiert.", "Sélection et classification des risques basées sur optimizerDuck d'itsfatduck (GPL-3.0), implémentées indépendamment dans RNX.", "设置选择和风险分级参考 itsfatduck 的 optimizerDuck（GPL-3.0），由 RNX 独立实现。"],
        ["ws.state.on"] = ["Applied", "Aplicado", "Применено", "Angewendet", "Appliqué", "已应用"],
        ["ws.state.rnx"] = ["Applied with RNX · can be undone", "Aplicado con RNX · se puede deshacer", "Применено через RNX · можно отменить", "Mit RNX angewendet · rückgängig machbar", "Appliqué avec RNX · annulable", "已通过 RNX 应用 · 可撤销"],
        ["ws.state.off"] = ["Not applied", "No aplicado", "Не применено", "Nicht angewendet", "Non appliqué", "未应用"],
        ["ws.risky.t"] = ["Apply \"{0}\"?", "¿Aplicar \"{0}\"?", "Применить «{0}»?", "„{0}“ anwenden?", "Appliquer « {0} » ?", "应用“{0}”？"],
        ["ws.risky.x"] = ["This setting is classified as risky: it can disable functions that some users need. The previous state is saved and can be restored by turning it off again. A restart is required.", "Este ajuste está clasificado como arriesgado: puede desactivar funciones que algunos usuarios necesitan. El estado anterior se guarda y puede restaurarse desactivándolo de nuevo. Requiere reiniciar.", "Этот параметр отмечен как рискованный: он может отключить функции, нужные некоторым пользователям. Прежнее состояние сохраняется и восстанавливается повторным отключением. Требуется перезагрузка.", "Diese Einstellung ist als riskant eingestuft: Sie kann Funktionen deaktivieren, die manche Benutzer benötigen. Der vorherige Zustand wird gespeichert und durch erneutes Ausschalten wiederhergestellt. Neustart erforderlich.", "Ce réglage est classé risqué : il peut désactiver des fonctions dont certains utilisateurs ont besoin. L'état précédent est enregistré et peut être rétabli en le désactivant. Redémarrage requis.", "此设置被标为高风险：可能会禁用部分用户需要的功能。之前的状态会被保存，再次关闭即可恢复。需要重启。"],
        ["ws.apply"] = ["Apply", "Aplicar", "Применить", "Anwenden", "Appliquer", "应用"],
        ["ws.ok"] = ["OK", "Aceptar", "ОК", "OK", "OK", "确定"],
        ["ws.noundo.t"] = ["This setting was not applied from RNX", "Este ajuste no se aplicó desde RNX", "Этот параметр применён не через RNX", "Diese Einstellung wurde nicht über RNX angewendet", "Ce réglage n'a pas été appliqué depuis RNX", "此设置并非通过 RNX 应用"],
        ["ws.noundo.x"] = ["It is already active on this computer (applied by Windows, another tool or a previous installation), so there is no saved previous state to restore.", "Ya está activo en este equipo (aplicado por Windows, otra herramienta o una instalación anterior), por lo que no hay un estado anterior guardado que restaurar.", "Он уже активен на этом компьютере (Windows, другой программой или прежней установкой), поэтому сохранённого состояния для восстановления нет.", "Sie ist auf diesem Computer bereits aktiv (durch Windows, ein anderes Tool oder eine frühere Installation), daher gibt es keinen gespeicherten Zustand zum Wiederherstellen.", "Il est déjà actif sur cet ordinateur (appliqué par Windows, un autre outil ou une installation précédente) : aucun état précédent n'est enregistré.", "该设置已在此电脑上生效（由 Windows、其他工具或之前的安装应用），因此没有可恢复的已保存状态。"],
        ["ws.toast.on"] = ["{0} applied.", "{0}: aplicado.", "{0}: применено.", "{0} angewendet.", "{0} appliqué.", "{0}：已应用。"],
        ["ws.toast.off"] = ["{0} undone.", "{0}: deshecho.", "{0}: отменено.", "{0} rückgängig gemacht.", "{0} annulé.", "{0}：已撤销。"],
        ["ws.toast.partial"] = ["{0}: {1} changes could not be applied. See the Log.", "{0}: {1} cambios no se han podido aplicar. Consulta el Registro.", "{0}: не удалось применить изменений: {1}. См. журнал.", "{0}: {1} Änderungen konnten nicht angewendet werden. Siehe Protokoll.", "{0} : {1} modifications n'ont pas pu être appliquées. Consultez le Journal.", "{0}：{1} 项更改未能应用。请查看日志。"],
        ["ws.restart"] = ["Restart to apply all changes.", "Reinicia para aplicar todos los cambios.", "Перезагрузите компьютер, чтобы применить изменения.", "Neu starten, um alle Änderungen anzuwenden.", "Redémarrez pour appliquer toutes les modifications.", "重启以应用全部更改。"],
        ["ws.toast.allSafe"] = ["All safe settings are already applied", "Todos los ajustes seguros ya están aplicados", "Все безопасные параметры уже применены", "Alle sicheren Einstellungen sind bereits angewendet", "Tous les réglages sûrs sont déjà appliqués", "所有安全设置均已应用"],
        ["ws.safe.t"] = ["Apply {0} safe settings?", "¿Aplicar {0} ajustes seguros?", "Применить безопасные параметры ({0})?", "{0} sichere Einstellungen anwenden?", "Appliquer {0} réglages sûrs ?", "应用 {0} 项安全设置？"],
        ["ws.safe.x"] = ["The previous state of each setting is saved so it can be undone individually. A restore point is created first if enabled in Settings.", "Se guarda el estado anterior de cada ajuste para poder deshacerlo individualmente. Si está activado en Ajustes, antes se crea un punto de restauración.", "Прежнее состояние каждого параметра сохраняется для отдельной отмены. Если включено в настройках, сначала создаётся точка восстановления.", "Der vorherige Zustand jeder Einstellung wird gespeichert, sodass sie einzeln rückgängig gemacht werden kann. Falls aktiviert, wird zuvor ein Wiederherstellungspunkt erstellt.", "L'état précédent de chaque réglage est enregistré pour pouvoir l'annuler individuellement. Un point de restauration est créé au préalable s'il est activé dans Paramètres.", "每项设置的之前状态都会保存，可单独撤销。若在“设置”中启用，将先创建还原点。"],
        ["ws.toast.safe"] = ["{0} safe settings applied.", "{0} ajustes seguros aplicados.", "Применено безопасных параметров: {0}.", "{0} sichere Einstellungen angewendet.", "{0} réglages sûrs appliqués.", "已应用 {0} 项安全设置。"],
        ["ws.apps.selSafe"] = ["Select safe apps", "Seleccionar las seguras", "Выбрать безопасные", "Sichere auswählen", "Sélectionner les sûres", "选择安全应用"],
        ["ws.apps.remove"] = ["Uninstall ({0})", "Desinstalar ({0})", "Удалить ({0})", "Deinstallieren ({0})", "Désinstaller ({0})", "卸载（{0}）"],
        ["ws.apps.none"] = ["No removable apps found", "No se han encontrado apps que puedan quitarse", "Удаляемые приложения не найдены", "Keine entfernbaren Apps gefunden", "Aucune application supprimable trouvée", "未找到可移除的应用"],
        ["ws.apps.warn"] = ["Uninstalling only affects the current user. Apps can be reinstalled from Microsoft Store. \"Safe\" apps can be removed without affecting Windows; \"Moderate\" apps are useful to many users (Photos, Calculator, Xbox, codecs).", "La desinstalación solo afecta al usuario actual. Las apps pueden reinstalarse desde Microsoft Store. Las \"Seguras\" pueden quitarse sin afectar a Windows; las \"Moderadas\" son útiles para muchos usuarios (Fotos, Calculadora, Xbox, códecs).", "Удаление затрагивает только текущего пользователя. Приложения можно переустановить из Microsoft Store. «Безопасные» удаляются без влияния на Windows; «Умеренные» полезны многим (Фотографии, Калькулятор, Xbox, кодеки).", "Die Deinstallation betrifft nur den aktuellen Benutzer. Apps lassen sich aus dem Microsoft Store neu installieren. „Sichere“ Apps können ohne Auswirkung auf Windows entfernt werden; „mittlere“ sind für viele nützlich (Fotos, Rechner, Xbox, Codecs).", "La désinstallation ne concerne que l'utilisateur actuel. Les applications peuvent être réinstallées depuis Microsoft Store. Les « sûres » se suppriment sans affecter Windows ; les « modérées » sont utiles à beaucoup (Photos, Calculatrice, Xbox, codecs).", "卸载仅影响当前用户，可从 Microsoft Store 重新安装。“安全”应用可移除且不影响 Windows；“中等”应用对许多用户有用（照片、计算器、Xbox、编解码器）。"],
        ["ws.apps.g.safe"] = ["Safe to remove ({0})", "Seguras de quitar ({0})", "Безопасно удалить ({0})", "Sicher entfernbar ({0})", "Suppression sûre ({0})", "可安全移除（{0}）"],
        ["ws.apps.g.caution"] = ["Use caution ({0})", "Con precaución ({0})", "С осторожностью ({0})", "Mit Vorsicht ({0})", "Avec précaution ({0})", "谨慎移除（{0}）"],
        ["ws.apps.g.other"] = ["Other apps ({0})", "Otras apps ({0})", "Другие приложения ({0})", "Weitere Apps ({0})", "Autres applications ({0})", "其他应用（{0}）"],
        ["ws.apps.t"] = ["Uninstall {0} apps?", "¿Desinstalar {0} apps?", "Удалить приложения ({0})?", "{0} Apps deinstallieren?", "Désinstaller {0} applications ?", "卸载 {0} 个应用？"],
        ["ws.apps.x"] = ["They are removed for the current user. This cannot be undone from RNX; they can be reinstalled from Microsoft Store.", "Se eliminan para el usuario actual. No puede deshacerse desde RNX; pueden reinstalarse desde Microsoft Store.", "Приложения удаляются для текущего пользователя. Отменить это в RNX нельзя; их можно переустановить из Microsoft Store.", "Sie werden für den aktuellen Benutzer entfernt. Dies kann in RNX nicht rückgängig gemacht werden; Neuinstallation über den Microsoft Store möglich.", "Elles sont supprimées pour l'utilisateur actuel. Cette action ne peut pas être annulée depuis RNX ; elles peuvent être réinstallées depuis Microsoft Store.", "将为当前用户移除这些应用。无法在 RNX 中撤销，可从 Microsoft Store 重新安装。"],
        ["ws.apps.btn"] = ["Uninstall", "Desinstalar", "Удалить", "Deinstallieren", "Désinstaller", "卸载"],
        ["ws.apps.toast"] = ["{0} apps uninstalled, {1} failed", "{0} apps desinstaladas, {1} con error", "Удалено: {0}, ошибок: {1}", "{0} Apps deinstalliert, {1} fehlgeschlagen", "{0} applications désinstallées, {1} en échec", "已卸载 {0} 个应用，{1} 个失败"],
        ["ws.startup.none"] = ["No startup programs found", "No hay programas de inicio", "Программ автозагрузки нет", "Keine Autostart-Programme gefunden", "Aucun programme au démarrage", "未找到启动程序"],
        ["ws.startup.on"] = ["{0} will start with Windows", "{0} se iniciará con Windows", "{0} будет запускаться с Windows", "{0} startet mit Windows", "{0} démarrera avec Windows", "{0} 将随 Windows 启动"],
        ["ws.startup.off"] = ["{0} will no longer start with Windows", "{0} ya no se iniciará con Windows", "{0} больше не будет запускаться с Windows", "{0} startet nicht mehr mit Windows", "{0} ne démarrera plus avec Windows", "{0} 将不再随 Windows 启动"],
        ["ws.st.user"] = ["Current user", "Usuario actual", "Текущий пользователь", "Aktueller Benutzer", "Utilisateur actuel", "当前用户"],
        ["ws.st.all"] = ["All users", "Todos los usuarios", "Все пользователи", "Alle Benutzer", "Tous les utilisateurs", "所有用户"],
        ["ws.st.folder"] = ["Startup folder", "Carpeta Inicio", "Папка автозагрузки", "Autostart-Ordner", "Dossier Démarrage", "启动文件夹"],
        ["ws.tasks.none"] = ["No third-party scheduled tasks found", "No hay tareas programadas de terceros", "Сторонних запланированных заданий нет", "Keine geplanten Aufgaben von Drittanbietern", "Aucune tâche planifiée tierce", "未找到第三方计划任务"],
        ["ws.tasks.on"] = ["{0} enabled", "{0} activada", "{0} включено", "{0} aktiviert", "{0} activée", "{0} 已启用"],
        ["ws.tasks.off"] = ["{0} disabled", "{0} desactivada", "{0} отключено", "{0} deaktiviert", "{0} désactivée", "{0} 已禁用"],
        ["ws.tasks.next"] = ["next run {0}", "próxima ejecución {0}", "следующий запуск {0}", "nächste Ausführung {0}", "prochaine exécution {0}", "下次运行 {0}"],
        ["lg.wt.applied"] = ["WINDOWS: {0} applied ({1} changes, {2} errors)", "WINDOWS: {0} aplicado ({1} cambios, {2} errores)", "WINDOWS: {0} применено ({1} изменений, {2} ошибок)", "WINDOWS: {0} angewendet ({1} Änderungen, {2} Fehler)", "WINDOWS : {0} appliqué ({1} modifications, {2} erreurs)", "WINDOWS：已应用 {0}（{1} 项更改，{2} 个错误）"],
        ["lg.wt.undone"] = ["WINDOWS: {0} undone ({1} values restored, {2} errors)", "WINDOWS: {0} deshecho ({1} valores restaurados, {2} errores)", "WINDOWS: {0} отменено (восстановлено {1}, ошибок {2})", "WINDOWS: {0} rückgängig gemacht ({1} Werte wiederhergestellt, {2} Fehler)", "WINDOWS : {0} annulé ({1} valeurs rétablies, {2} erreurs)", "WINDOWS：已撤销 {0}（恢复 {1} 项，{2} 个错误）"],
        ["lg.wt.fail"] = ["WINDOWS: error: {0}", "WINDOWS: error: {0}", "WINDOWS: ошибка: {0}", "WINDOWS: Fehler: {0}", "WINDOWS : erreur : {0}", "WINDOWS：错误：{0}"],
        ["lg.wa.removed"] = ["APPS: {0} uninstalled", "APPS: {0} desinstalada", "ПРИЛОЖЕНИЯ: {0} удалено", "APPS: {0} deinstalliert", "APPLICATIONS : {0} désinstallée", "应用：已卸载 {0}"],
        ["lg.wa.fail"] = ["APPS: {0} could not be uninstalled: {1}", "APPS: no se ha podido desinstalar {0}: {1}", "ПРИЛОЖЕНИЯ: не удалось удалить {0}: {1}", "APPS: {0} konnte nicht deinstalliert werden: {1}", "APPLICATIONS : impossible de désinstaller {0} : {1}", "应用：无法卸载 {0}：{1}"],
        ["lg.ws.stOn"] = ["STARTUP: {0} enabled", "INICIO: {0} activado", "АВТОЗАГРУЗКА: {0} включено", "AUTOSTART: {0} aktiviert", "DÉMARRAGE : {0} activé", "启动项：已启用 {0}"],
        ["lg.ws.stOff"] = ["STARTUP: {0} disabled", "INICIO: {0} desactivado", "АВТОЗАГРУЗКА: {0} отключено", "AUTOSTART: {0} deaktiviert", "DÉMARRAGE : {0} désactivé", "启动项：已禁用 {0}"],
        ["lg.ws.tkOn"] = ["TASKS: {0} enabled", "TAREAS: {0} activada", "ЗАДАНИЯ: {0} включено", "AUFGABEN: {0} aktiviert", "TÂCHES : {0} activée", "任务：已启用 {0}"],
        ["lg.ws.tkOff"] = ["TASKS: {0} disabled", "TAREAS: {0} desactivada", "ЗАДАНИЯ: {0} отключено", "AUFGABEN: {0} deaktiviert", "TÂCHES : {0} désactivée", "任务：已禁用 {0}"],
        ["wt.bgapps"] = ["Disable background apps", "Desactivar apps en segundo plano", "Отключить фоновые приложения", "Hintergrund-Apps deaktivieren", "Désactiver les applications en arrière-plan", "禁用后台应用"],
        ["wt.bgapps.d"] = ["Store apps stop running in the background, saving RAM and CPU. Notifications from some apps may arrive late.", "Las apps de la Store dejan de ejecutarse en segundo plano y se ahorra RAM y CPU. Las notificaciones de algunas apps pueden llegar con retraso.", "Приложения Store не работают в фоне, экономя RAM и CPU. Уведомления некоторых приложений могут задерживаться.", "Store-Apps laufen nicht mehr im Hintergrund; das spart RAM und CPU. Benachrichtigungen mancher Apps können verzögert eintreffen.", "Les applications du Store ne s'exécutent plus en arrière-plan, ce qui économise RAM et CPU. Certaines notifications peuvent arriver en retard.", "应用商店应用不再在后台运行，节省内存和 CPU。部分应用的通知可能延迟。"],
        ["wt.svchost"] = ["Group service host processes", "Agrupar procesos de servicios", "Объединить процессы служб", "Diensthost-Prozesse bündeln", "Regrouper les processus hôtes de services", "合并服务宿主进程"],
        ["wt.svchost.d"] = ["Windows groups services into fewer svchost.exe processes according to the installed RAM, reducing overhead.", "Windows agrupa los servicios en menos procesos svchost.exe según la RAM instalada, lo que reduce la sobrecarga.", "Windows объединяет службы в меньшее число процессов svchost.exe в зависимости от объёма RAM, снижая издержки.", "Windows bündelt Dienste je nach installiertem RAM in weniger svchost.exe-Prozessen und reduziert so den Overhead.", "Windows regroupe les services dans moins de processus svchost.exe selon la RAM installée, ce qui réduit la surcharge.", "Windows 根据已安装内存将服务合并到更少的 svchost.exe 进程中，降低开销。"],
        ["wt.priority"] = ["Prioritise the foreground program", "Priorizar el programa en primer plano", "Приоритет активной программы", "Vordergrundprogramm priorisieren", "Prioriser le programme au premier plan", "优先前台程序"],
        ["wt.priority.d"] = ["Short, variable processor time slices with a high boost for the active window (the game).", "Intervalos de procesador cortos y variables con mayor prioridad para la ventana activa (el juego).", "Короткие переменные кванты процессорного времени с повышенным приоритетом активного окна (игры).", "Kurze, variable Prozessorzeitscheiben mit hoher Priorität für das aktive Fenster (das Spiel).", "Tranches de temps processeur courtes et variables avec un fort coup de pouce pour la fenêtre active (le jeu).", "采用短且可变的处理器时间片，并大幅提升活动窗口（游戏）的优先级。"],
        ["wt.mmcss"] = ["Optimise the multimedia scheduler", "Optimizar el programador multimedia", "Оптимизировать мультимедийный планировщик", "Multimedia-Planer optimieren", "Optimiser le planificateur multimédia", "优化多媒体调度程序"],
        ["wt.mmcss.d"] = ["Gives games maximum CPU and GPU priority and removes network throttling during multimedia playback.", "Da a los juegos la máxima prioridad de CPU y GPU y elimina la limitación de red durante la reproducción multimedia.", "Даёт играм максимальный приоритет CPU и GPU и снимает ограничение сети при воспроизведении мультимедиа.", "Gibt Spielen höchste CPU- und GPU-Priorität und hebt die Netzwerkdrosselung bei Multimediawiedergabe auf.", "Donne aux jeux la priorité CPU et GPU maximale et supprime la limitation réseau pendant la lecture multimédia.", "为游戏提供最高 CPU 和 GPU 优先级，并取消多媒体播放时的网络限速。"],
        ["wt.keyboard"] = ["Minimum keyboard delay", "Retardo de teclado mínimo", "Минимальная задержка клавиатуры", "Minimale Tastaturverzögerung", "Délai clavier minimal", "最小键盘延迟"],
        ["wt.keyboard.d"] = ["Shortest repeat delay and fastest repeat rate for held keys.", "Menor retardo y mayor velocidad de repetición al mantener una tecla pulsada.", "Минимальная задержка и максимальная скорость повтора при удержании клавиши.", "Kürzeste Verzögerung und schnellste Wiederholrate für gehaltene Tasten.", "Délai de répétition le plus court et vitesse de répétition maximale pour les touches maintenues.", "按住按键时重复延迟最短、重复速度最快。"],
        ["wt.a11ykeys"] = ["Disable accessibility shortcuts", "Desactivar atajos de accesibilidad", "Отключить сочетания специальных возможностей", "Bedienungshilfen-Tastenkürzel deaktivieren", "Désactiver les raccourcis d'accessibilité", "禁用辅助功能快捷键"],
        ["wt.a11ykeys.d"] = ["Prevents Sticky Keys, Filter Keys and Toggle Keys from opening when pressing Shift or Num Lock repeatedly in game.", "Evita que Teclas especiales, Teclas filtro y Teclas de alternancia se abran al pulsar Mayús o Bloq Num repetidamente en el juego.", "Не даёт залипанию, фильтрации и озвучиванию клавиш включаться при многократном нажатии Shift или Num Lock в игре.", "Verhindert, dass Einrastfunktion, Anschlagverzögerung und Statusanzeige beim mehrfachen Drücken von Umschalt oder Num in Spielen erscheinen.", "Empêche l'ouverture des touches rémanentes, filtres et bascules lors d'appuis répétés sur Maj ou Verr Num en jeu.", "防止在游戏中连续按 Shift 或 Num Lock 时弹出粘滞键、筛选键和切换键。"],
        ["wt.throttling"] = ["Disable power throttling", "Desactivar la limitación de energía", "Отключить ограничение питания", "Energiedrosselung deaktivieren", "Désactiver la limitation d'énergie", "禁用电源限制"],
        ["wt.throttling.d"] = ["Windows no longer throttles background processes to save energy, and USB power drain recovery is disabled.", "Windows deja de limitar los procesos en segundo plano para ahorrar energía y se desactiva la recuperación por consumo USB.", "Windows перестаёт ограничивать фоновые процессы ради экономии энергии, отключается восстановление при перегрузке USB.", "Windows drosselt Hintergrundprozesse nicht mehr zum Energiesparen; die USB-Stromwiederherstellung wird deaktiviert.", "Windows ne bride plus les processus en arrière-plan pour économiser l'énergie et la récupération de consommation USB est désactivée.", "Windows 不再为节能而限制后台进程，并禁用 USB 耗电恢复。"],
        ["wt.usbpower"] = ["Disable USB power saving", "Desactivar el ahorro de energía USB", "Отключить энергосбережение USB", "USB-Energiesparen deaktivieren", "Désactiver l'économie d'énergie USB", "禁用 USB 节能"],
        ["wt.usbpower.d"] = ["Windows can no longer power down the USB root hubs, avoiding mouse or keyboard wake-up delays.", "Windows ya no puede apagar los concentradores raíz USB, lo que evita retrasos al reactivar el ratón o el teclado.", "Windows больше не отключает корневые USB-концентраторы, что исключает задержки пробуждения мыши и клавиатуры.", "Windows kann die USB-Root-Hubs nicht mehr abschalten; das vermeidet Aufwachverzögerungen bei Maus und Tastatur.", "Windows ne peut plus mettre en veille les concentrateurs USB racine, ce qui évite les délais de réveil de la souris ou du clavier.", "Windows 不再关闭 USB 根集线器，避免鼠标或键盘唤醒延迟。"],
        ["wt.hibernate"] = ["Disable hibernation and fast startup", "Desactivar hibernación e inicio rápido", "Отключить гибернацию и быстрый запуск", "Ruhezustand und Schnellstart deaktivieren", "Désactiver la veille prolongée et le démarrage rapide", "禁用休眠和快速启动"],
        ["wt.hibernate.d"] = ["Frees the space of hiberfil.sys and makes every shutdown a full restart of the system.", "Libera el espacio de hiberfil.sys y hace que cada apagado sea un arranque completo del sistema.", "Освобождает место hiberfil.sys, каждое выключение становится полным перезапуском системы.", "Gibt den Speicher von hiberfil.sys frei; jedes Herunterfahren wird zu einem vollständigen Systemstart.", "Libère l'espace de hiberfil.sys et fait de chaque arrêt un redémarrage complet du système.", "释放 hiberfil.sys 占用的空间，每次关机后都会完整启动系统。"],
        ["wt.webdav"] = ["Remove the WebDAV file size limit", "Quitar el límite de tamaño de WebDAV", "Снять ограничение размера WebDAV", "WebDAV-Dateigrößenlimit aufheben", "Supprimer la limite de taille WebDAV", "取消 WebDAV 文件大小限制"],
        ["wt.webdav.d"] = ["Allows files larger than 50 MB to be copied over WebDAV network drives.", "Permite copiar archivos de más de 50 MB en unidades de red WebDAV.", "Позволяет копировать файлы больше 50 МБ на сетевые диски WebDAV.", "Ermöglicht das Kopieren von Dateien über 50 MB auf WebDAV-Netzlaufwerke.", "Permet de copier des fichiers de plus de 50 Mo sur les lecteurs réseau WebDAV.", "允许在 WebDAV 网络驱动器上复制大于 50 MB 的文件。"],
        ["wt.nv.pstate"] = ["NVIDIA: disable dynamic P-states", "NVIDIA: desactivar P-states dinámicos", "NVIDIA: отключить динамические P-состояния", "NVIDIA: dynamische P-States deaktivieren", "NVIDIA : désactiver les P-states dynamiques", "NVIDIA：禁用动态 P 状态"],
        ["wt.nv.pstate.d"] = ["The graphics card stays at higher clocks instead of lowering them dynamically, reducing frame time variation. Increases idle power consumption.", "La gráfica se mantiene a frecuencias altas en lugar de bajarlas dinámicamente, lo que reduce la variación del frametime. Aumenta el consumo en reposo.", "Видеокарта держит высокие частоты вместо динамического снижения, уменьшая разброс frametime. Повышает потребление в простое.", "Die Grafikkarte bleibt auf höheren Takten, statt sie dynamisch zu senken; das verringert Frametime-Schwankungen. Erhöht den Leerlaufverbrauch.", "La carte graphique reste à des fréquences élevées au lieu de les abaisser dynamiquement, ce qui réduit la variation du frametime. Augmente la consommation au repos.", "显卡保持较高频率而非动态降频，减少帧时间波动。会增加待机功耗。"],
        ["wt.nv.async"] = ["NVIDIA: disable asynchronous P-states", "NVIDIA: desactivar P-states asíncronos", "NVIDIA: отключить асинхронные P-состояния", "NVIDIA: asynchrone P-States deaktivieren", "NVIDIA : désactiver les P-states asynchrones", "NVIDIA：禁用异步 P 状态"],
        ["wt.nv.async.d"] = ["Prevents memory and core clocks from changing independently. May increase temperature and consumption.", "Evita que las frecuencias de memoria y núcleo cambien de forma independiente. Puede aumentar la temperatura y el consumo.", "Не даёт частотам памяти и ядра меняться независимо. Может повысить температуру и потребление.", "Verhindert, dass Speicher- und Kerntakt unabhängig voneinander wechseln. Kann Temperatur und Verbrauch erhöhen.", "Empêche les fréquences mémoire et cœur de varier indépendamment. Peut augmenter la température et la consommation.", "防止显存与核心频率独立变化。可能提高温度和功耗。"],
        ["wt.amd.ulps"] = ["AMD: disable ULPS", "AMD: desactivar ULPS", "AMD: отключить ULPS", "AMD: ULPS deaktivieren", "AMD : désactiver ULPS", "AMD：禁用 ULPS"],
        ["wt.amd.ulps.d"] = ["Disables Ultra Low Power State, which can cause wake-up stutter and instability in multi-GPU setups.", "Desactiva Ultra Low Power State, que puede causar tirones al reactivarse e inestabilidad con varias GPU.", "Отключает Ultra Low Power State, способный вызывать подтормаживания при пробуждении и нестабильность с несколькими GPU.", "Deaktiviert den Ultra Low Power State, der Aufwach-Ruckler und Instabilität bei mehreren GPUs verursachen kann.", "Désactive l'Ultra Low Power State, source de saccades au réveil et d'instabilité en multi-GPU.", "禁用超低功耗状态，该状态可能导致唤醒卡顿和多 GPU 不稳定。"],
        ["wt.amd.gating"] = ["AMD: disable power gating", "AMD: desactivar power gating", "AMD: отключить power gating", "AMD: Power Gating deaktivieren", "AMD : désactiver le power gating", "AMD：禁用电源门控"],
        ["wt.amd.gating.d"] = ["Keeps GPU blocks powered and disables dynamic power states for more consistent performance. Increases consumption.", "Mantiene alimentados los bloques de la GPU y desactiva los estados dinámicos para un rendimiento más constante. Aumenta el consumo.", "Блоки GPU остаются под питанием, динамические состояния отключаются для стабильной производительности. Повышает потребление.", "Hält GPU-Blöcke unter Spannung und deaktiviert dynamische Zustände für gleichmäßigere Leistung. Erhöht den Verbrauch.", "Maintient l'alimentation des blocs du GPU et désactive les états dynamiques pour des performances plus constantes. Augmente la consommation.", "保持 GPU 模块供电并禁用动态功耗状态，性能更稳定。会增加功耗。"],
        ["wt.amd.vce"] = ["AMD: disable video engine clock gating", "AMD: desactivar clock gating del motor de vídeo", "AMD: отключить clock gating видеодвижка", "AMD: Clock Gating der Video-Engine deaktivieren", "AMD : désactiver le clock gating du moteur vidéo", "AMD：禁用视频引擎时钟门控"],
        ["wt.amd.vce.d"] = ["Keeps the encoder and decoder (VCE/UVD) active, avoiding delays when recording or streaming.", "Mantiene activos el codificador y el decodificador (VCE/UVD) y evita retrasos al grabar o retransmitir.", "Кодировщик и декодер (VCE/UVD) остаются активными, исключая задержки при записи и трансляции.", "Hält Encoder und Decoder (VCE/UVD) aktiv und vermeidet Verzögerungen beim Aufnehmen oder Streamen.", "Maintient l'encodeur et le décodeur (VCE/UVD) actifs, évitant les délais lors de l'enregistrement ou du streaming.", "保持编码器和解码器（VCE/UVD）处于活动状态，避免录制或直播时延迟。"],
        ["wt.amd.aspm"] = ["AMD: disable PCIe ASPM", "AMD: desactivar PCIe ASPM", "AMD: отключить PCIe ASPM", "AMD: PCIe-ASPM deaktivieren", "AMD : désactiver PCIe ASPM", "AMD：禁用 PCIe ASPM"],
        ["wt.amd.aspm.d"] = ["Disables PCIe link power saving (L0s/L1), removing link wake-up latency.", "Desactiva el ahorro de energía del enlace PCIe (L0s/L1) y elimina la latencia de reactivación.", "Отключает энергосбережение канала PCIe (L0s/L1), устраняя задержку пробуждения.", "Deaktiviert das PCIe-Link-Energiesparen (L0s/L1) und entfernt die Aufwachlatenz.", "Désactive l'économie d'énergie du lien PCIe (L0s/L1) et supprime la latence de réveil.", "禁用 PCIe 链路节能（L0s/L1），消除唤醒延迟。"],
        ["wt.intel.flips"] = ["Intel: disable asynchronous flips", "Intel: desactivar flips asíncronos", "Intel: отключить асинхронные flips", "Intel: asynchrone Flips deaktivieren", "Intel : désactiver les flips asynchrones", "Intel：禁用异步翻转"],
        ["wt.intel.flips.d"] = ["Reduces tearing and stutter on Intel integrated graphics.", "Reduce el tearing y los tirones en gráficas integradas Intel.", "Уменьшает разрывы и подтормаживания на встроенной графике Intel.", "Verringert Tearing und Ruckler bei Intel-Grafik.", "Réduit le tearing et les saccades sur les puces graphiques Intel.", "减少 Intel 集成显卡的画面撕裂和卡顿。"],
        ["wt.intel.vsync"] = ["Intel: disable adaptive V-Sync", "Intel: desactivar V-Sync adaptativo", "Intel: отключить адаптивный V-Sync", "Intel: adaptives V-Sync deaktivieren", "Intel : désactiver le V-Sync adaptatif", "Intel：禁用自适应垂直同步"],
        ["wt.intel.vsync.d"] = ["Prevents the driver from enabling V-Sync on its own, which adds input latency.", "Evita que el controlador active V-Sync por su cuenta, lo que añade latencia.", "Не даёт драйверу самостоятельно включать V-Sync, добавляющий задержку ввода.", "Verhindert, dass der Treiber V-Sync selbst aktiviert, was die Eingabelatenz erhöht.", "Empêche le pilote d'activer lui-même le V-Sync, qui ajoute de la latence.", "防止驱动自行启用会增加输入延迟的垂直同步。"],
        ["wt.telemetry"] = ["Disable Windows telemetry", "Desactivar la telemetría de Windows", "Отключить телеметрию Windows", "Windows-Telemetrie deaktivieren", "Désactiver la télémétrie de Windows", "禁用 Windows 遥测"],
        ["wt.telemetry.d"] = ["Minimum diagnostic data, telemetry services disabled (DiagTrack and others) and compatibility and CEIP tasks turned off.", "Datos de diagnóstico mínimos, servicios de telemetría desactivados (DiagTrack y otros) y tareas de compatibilidad y CEIP apagadas.", "Минимум диагностических данных, службы телеметрии (DiagTrack и др.) отключены, задачи совместимости и CEIP выключены.", "Minimale Diagnosedaten, Telemetriedienste (DiagTrack u. a.) deaktiviert sowie Kompatibilitäts- und CEIP-Aufgaben ausgeschaltet.", "Données de diagnostic minimales, services de télémétrie (DiagTrack et autres) désactivés et tâches de compatibilité et CEIP arrêtées.", "最少诊断数据，禁用遥测服务（DiagTrack 等），并关闭兼容性和 CEIP 任务。"],
