        ["nvd.c.nvpcf"] = ["Power management for laptops. Recommended on laptops.", "Gestión de energía para portátiles. Recomendado en portátiles.", "Управление питанием ноутбуков. Рекомендуется для ноутбуков.", "Energieverwaltung für Laptops. Für Laptops empfohlen.", "Gestion de l'énergie des ordinateurs portables. Recommandé sur portable.", "笔记本电源管理。笔记本推荐安装。"],
