        ["nvd.badge"] = ["New", "Nuevo", "Новый", "Neu", "Nouveau", "新"],
        ["nvd.toast"] = ["New NVIDIA driver version available: {0}", "Nueva versión del controlador NVIDIA disponible: {0}", "Доступна новая версия драйвера NVIDIA: {0}", "Neue NVIDIA-Treiberversion verfügbar: {0}", "Nouvelle version du pilote NVIDIA disponible : {0}", "有新版 NVIDIA 驱动可用：{0}"],
        ["nvd.alert.t"] = ["NVIDIA driver out of date · Current version: {0}", "Controlador NVIDIA desactualizado · Versión actual: {0}", "Драйвер NVIDIA устарел · Текущая версия: {0}", "NVIDIA-Treiber veraltet · Aktuelle Version: {0}", "Pilote NVIDIA obsolète · Version actuelle : {0}", "NVIDIA 驱动已过时 · 当前版本：{0}"],
        ["nvd.alert.x"] = ["Installed version: {0} · {1} versions behind · Released on {2} ({3} days ago).", "Versión instalada: {0} · {1} versiones por detrás · Publicada el {2} (hace {3} días).", "Установленная версия: {0} · отставание: {1} версий · Выпущена {2} ({3} дн. назад).", "Installierte Version: {0} · {1} Versionen zurück · Veröffentlicht am {2} (vor {3} Tagen).", "Version installée : {0} · {1} versions de retard · Publiée le {2} (il y a {3} jours).", "已安装版本：{0} · 落后 {1} 个版本 · 发布于 {2}（{3} 天前）。"],
        ["nvd.alert.x1"] = ["Installed version: {0} · 1 version behind · Released on {2} ({3} days ago).", "Versión instalada: {0} · 1 versión por detrás · Publicada el {2} (hace {3} días).", "Установленная версия: {0} · отставание: 1 версия · Выпущена {2} ({3} дн. назад).", "Installierte Version: {0} · 1 Version zurück · Veröffentlicht am {2} (vor {3} Tagen).", "Version installée : {0} · 1 version de retard · Publiée le {2} (il y a {3} jours).", "已安装版本：{0} · 落后 1 个版本 · 发布于 {2}（{3} 天前）。"],
        ["lg.nvd.available"] = ["NVIDIA driver {0} available (installed: {1})", "Driver de NVIDIA {0} disponible (instalado: {1})", "Доступен драйвер NVIDIA {0} (установлен: {1})", "NVIDIA-Treiber {0} verfügbar (installiert: {1})", "Pilote NVIDIA {0} disponible (installé : {1})", "NVIDIA 驱动 {0} 可用（已安装：{1}）"],

        // ---------- 5.3.0: HUD ----------
        ["hud.pawnio.t"] = ["Install the PawnIO driver?", "¿Instalar el driver PawnIO?", "Установить драйвер PawnIO?", "PawnIO-Treiber installieren?", "Installer le pilote PawnIO ?", "安装 PawnIO 驱动？"],
        ["hud.pawnio.x"] = ["RNX will download the official installer (github.com/namazso/PawnIO.Setup), verify its digital signature and open it to complete the installation. PawnIO is a free, signed driver (GPL) used by LibreHardwareMonitor to read CPU temperature and clock. It can be uninstalled from Windows Settings → Apps.", "RNX descargará el instalador oficial (github.com/namazso/PawnIO.Setup), verificará su firma digital y lo abrirá para completar la instalación. PawnIO es un controlador gratuito y firmado (GPL) que LibreHardwareMonitor utiliza para leer la temperatura y la frecuencia de la CPU. Puede desinstalarse desde Configuración de Windows → Aplicaciones.", "RNX загрузит официальный установщик (github.com/namazso/PawnIO.Setup), проверит цифровую подпись и откроет его для завершения установки. PawnIO — бесплатный подписанный драйвер (GPL), который LibreHardwareMonitor использует для чтения температуры и частоты CPU. Удаляется через Параметры Windows → Приложения.", "RNX lädt den offiziellen Installer (github.com/namazso/PawnIO.Setup) herunter, prüft die digitale Signatur und öffnet ihn zur Installation. PawnIO ist ein kostenloser, signierter Treiber (GPL), den LibreHardwareMonitor zum Auslesen von CPU-Temperatur und -Takt verwendet. Deinstallation über Windows-Einstellungen → Apps.", "RNX téléchargera l'installateur officiel (github.com/namazso/PawnIO.Setup), vérifiera sa signature numérique et l'ouvrira pour terminer l'installation. PawnIO est un pilote gratuit et signé (GPL) utilisé par LibreHardwareMonitor pour lire la température et la fréquence du CPU. Il peut être désinstallé depuis Paramètres Windows → Applications.", "RNX 将下载官方安装程序（github.com/namazso/PawnIO.Setup），验证其数字签名并打开以完成安装。PawnIO 是免费且已签名的驱动（GPL），LibreHardwareMonitor 用它读取 CPU 温度和频率。可在 Windows 设置 → 应用 中卸载。"],
        ["hud.pawnio.downloading"] = ["Downloading the PawnIO installer…", "Descargando el instalador de PawnIO…", "Загрузка установщика PawnIO…", "PawnIO-Installer wird heruntergeladen…", "Téléchargement de l'installateur PawnIO…", "正在下载 PawnIO 安装程序…"],
        ["hud.pawnio.ok"] = ["PawnIO installed. CPU temperature and clock are now available.", "PawnIO instalado. Temperatura y frecuencia de la CPU disponibles.", "PawnIO установлен. Температура и частота CPU доступны.", "PawnIO installiert. CPU-Temperatur und -Takt sind verfügbar.", "PawnIO installé. Température et fréquence du CPU disponibles.", "PawnIO 已安装。CPU 温度和频率现已可用。"],
        ["hud.pawnio.reboot"] = ["Installer closed. If the CPU temperature does not appear, restart the computer.", "Instalador cerrado. Si la temperatura de la CPU no aparece, reinicia el equipo.", "Установщик закрыт. Если температура CPU не отображается, перезагрузите компьютер.", "Installer geschlossen. Wird die CPU-Temperatur nicht angezeigt, den Computer neu starten.", "Installateur fermé. Si la température du CPU n'apparaît pas, redémarrez l'ordinateur.", "安装程序已关闭。如未显示 CPU 温度，请重启电脑。"],
        ["lg.pawnio.signed"] = ["PAWNIO: installer downloaded, valid signature ({0})", "PAWNIO: instalador descargado, firma válida ({0})", "PAWNIO: установщик загружен, подпись действительна ({0})", "PAWNIO: Installer heruntergeladen, Signatur gültig ({0})", "PAWNIO : installateur téléchargé, signature valide ({0})", "PAWNIO：安装程序已下载，签名有效（{0}）"],
        ["lg.pawnio.badsig"] = ["PAWNIO: the downloaded installer does not have a valid signature; it was deleted without running it", "PAWNIO: el instalador descargado no tiene una firma válida; se ha eliminado sin ejecutarlo", "PAWNIO: у загруженного установщика недействительная подпись; он удалён без запуска", "PAWNIO: Der heruntergeladene Installer hat keine gültige Signatur und wurde ohne Ausführung gelöscht", "PAWNIO : l'installateur téléchargé n'a pas de signature valide ; il a été supprimé sans être exécuté", "PAWNIO：下载的安装程序签名无效，已删除且未运行"],
        ["lg.pawnio.done"] = ["PAWNIO: installer finished (code {0})", "PAWNIO: instalador terminado (código {0})", "PAWNIO: установщик завершён (код {0})", "PAWNIO: Installer beendet (Code {0})", "PAWNIO : installateur terminé (code {0})", "PAWNIO：安装程序已结束（代码 {0}）"],
        ["lg.pawnio.fail"] = ["PAWNIO: error: {0}", "PAWNIO: error: {0}", "PAWNIO: ошибка: {0}", "PAWNIO: Fehler: {0}", "PAWNIO : erreur : {0}", "PAWNIO：错误：{0}"],
        ["hud.title"] = ["Performance HUD", "HUD de rendimiento", "HUD производительности", "Leistungs-HUD", "HUD de performances", "性能 HUD"],
        ["hud.sub"] = ["An overlay showing FPS, frametime, CPU, GPU and RAM. It runs as a separate window with no injection into the game, so it is compatible with anti-cheat systems. Visible in borderless window mode and in Windows 11 fullscreen.", "Superposición con FPS, frametime, CPU, GPU y RAM. Se ejecuta como ventana independiente, sin inyección en el juego, por lo que es compatible con los sistemas anticheat. Visible en modo ventana sin bordes y en pantalla completa de Windows 11.", "Оверлей с FPS, frametime, CPU, GPU и RAM. Работает как отдельное окно без внедрения в игру, поэтому совместим с античитами. Отображается в оконном режиме без рамки и в полноэкранном режиме Windows 11.", "Overlay mit FPS, Frametime, CPU, GPU und RAM. Läuft als separates Fenster ohne Injektion ins Spiel und ist daher mit Anti-Cheat-Systemen kompatibel. Sichtbar im randlosen Fenstermodus und im Vollbild von Windows 11.", "Superposition affichant FPS, frametime, CPU, GPU et RAM. Elle s'exécute dans une fenêtre distincte, sans injection dans le jeu, et reste donc compatible avec les anti-triche. Visible en fenêtré sans bordure et en plein écran sous Windows 11.", "显示 FPS、帧时间、CPU、GPU 和内存的覆盖层。以独立窗口运行，不注入游戏，因此与反作弊系统兼容。在无边框窗口模式和 Windows 11 全屏模式下可见。"],
        ["hud.enable"] = ["Show the HUD", "Mostrar el HUD", "Показывать HUD", "HUD anzeigen", "Afficher le HUD", "显示 HUD"],
        ["hud.state.off"] = ["Off", "Desactivado", "Выключено", "Aus", "Désactivé", "已关闭"],
        ["hud.state.visible"] = ["Enabled · visible", "Activado · visible", "Включён · отображается", "Aktiviert · sichtbar", "Activé · visible", "已启用 · 可见"],
        ["hud.state.hidden"] = ["Enabled · hidden (use the assigned key to show it)", "Activado · oculto (usa la tecla asignada para mostrarlo)", "Включён · скрыт (нажмите назначенную клавишу)", "Aktiviert · ausgeblendet (zugewiesene Taste zum Einblenden)", "Activé · masqué (utilisez la touche attribuée pour l'afficher)", "已启用 · 已隐藏（按指定按键显示）"],
        ["hud.pawnio"] = ["CPU temperature and clock readings require the PawnIO driver (free and signed; used by LibreHardwareMonitor). RNX can download and launch its official installer.", "La lectura de temperatura y frecuencia de la CPU requiere el controlador PawnIO (gratuito y firmado; utilizado por LibreHardwareMonitor). RNX puede descargar e iniciar su instalador oficial.", "Для чтения температуры и частоты CPU нужен драйвер PawnIO (бесплатный и подписанный; используется LibreHardwareMonitor). RNX может загрузить и запустить его официальный установщик.", "Für CPU-Temperatur und -Takt wird der Treiber PawnIO benötigt (kostenlos und signiert; von LibreHardwareMonitor verwendet). RNX kann den offiziellen Installer herunterladen und starten.", "La lecture de la température et de la fréquence du CPU nécessite le pilote PawnIO (gratuit et signé ; utilisé par LibreHardwareMonitor). RNX peut télécharger et lancer son installateur officiel.", "读取 CPU 温度和频率需要 PawnIO 驱动（免费且已签名，LibreHardwareMonitor 使用）。RNX 可下载并启动其官方安装程序。"],
        ["hud.pawnio.btn"] = ["Install PawnIO", "Instalar PawnIO", "Установить PawnIO", "PawnIO installieren", "Installer PawnIO", "安装 PawnIO"],
        ["hud.key"] = ["Show / hide key", "Tecla para mostrar u ocultar", "Клавиша показа / скрытия", "Taste zum Ein-/Ausblenden", "Touche afficher / masquer", "显示 / 隐藏按键"],
        ["hud.key.sub"] = ["Also works in game.", "Funciona también dentro del juego.", "Работает и в игре.", "Funktioniert auch im Spiel.", "Fonctionne aussi en jeu.", "在游戏中同样有效。"],
        ["hud.key.none"] = ["Not assigned", "Sin asignar", "Не назначена", "Nicht zugewiesen", "Non attribuée", "未分配"],
        ["hud.key.press"] = ["Press a key or key combination… (Esc to cancel)", "Pulsa una tecla o combinación… (Esc para cancelar)", "Нажмите клавишу или сочетание… (Esc — отмена)", "Taste oder Tastenkombination drücken… (Esc zum Abbrechen)", "Appuyez sur une touche ou une combinaison… (Échap pour annuler)", "请按下按键或组合键…（Esc 取消）"],
