        ["hud.style.sub"] = ["Classic (RivaTuner style), RNX panel or mixed.", "Clásico (estilo RivaTuner), panel RNX o mixto.", "Классический (в стиле RivaTuner), панель RNX или смешанный.", "Klassisch (RivaTuner-Stil), RNX-Panel oder gemischt.", "Classique (style RivaTuner), panneau RNX ou mixte.", "经典（RivaTuner 风格）、RNX 面板或混合。"],
        ["hud.style.a1"] = ["Classic", "Clásico", "Классический", "Klassisch", "Classique", "经典"],
        ["hud.style.c1"] = ["RNX panel", "Panel RNX", "Панель RNX", "RNX-Panel", "Panneau RNX", "RNX 面板"],
        ["hud.style.m"] = ["Mixed", "Mixto", "Смешанный", "Gemischt", "Mixte", "混合"],
        ["hud.pos"] = ["Position", "Posición", "Положение", "Position", "Position", "位置"],
        ["hud.pos.sub"] = ["Select one of the six positions, or unlock the HUD to place it with the mouse.", "Selecciona una de las seis posiciones o desbloquea el HUD para situarlo con el ratón.", "Выберите одну из шести позиций или разблокируйте HUD, чтобы разместить его мышью.", "Eine der sechs Positionen wählen oder das HUD entsperren, um es mit der Maus zu platzieren.", "Sélectionnez l'une des six positions ou déverrouillez le HUD pour le placer à la souris.", "选择六个位置之一，或解锁 HUD 后用鼠标放置。"],
