        ["hud.opacity"] = ["Background opacity", "Opacidad del fondo", "Непрозрачность фона", "Hintergrunddeckkraft", "Opacité de l'arrière-plan", "背景不透明度"],
        ["hud.rows"] = ["Displayed information", "Información mostrada", "Отображаемые данные", "Angezeigte Informationen", "Informations affichées", "显示内容"],
