        ["hud.preview"] = ["Preview", "Vista previa", "Предпросмотр", "Vorschau", "Aperçu", "预览"],
        ["hud.preview.demo"] = ["Sample data. Enable the HUD to see live data from this computer.", "Datos de ejemplo. Activa el HUD para ver los datos de este equipo.", "Пример данных. Включите HUD, чтобы видеть данные этого компьютера.", "Beispieldaten. HUD aktivieren, um Live-Daten dieses Computers zu sehen.", "Données d'exemple. Activez le HUD pour voir les données de cet ordinateur.", "示例数据。启用 HUD 以查看本机实时数据。"],
        ["hud.preview.live"] = ["Live · FPS source: {0}", "En directo · FPS de: {0}", "В реальном времени · FPS: {0}", "Live · FPS-Quelle: {0}", "En direct · source FPS : {0}", "实时 · FPS 来源：{0}"],
        ["hud.toast.on"] = ["HUD on", "HUD activado", "HUD включён", "HUD an", "HUD activé", "HUD 已开启"],
        ["hud.toast.off"] = ["HUD off", "HUD desactivado", "HUD выключен", "HUD aus", "HUD désactivé", "HUD 已关闭"],
        ["hud.toast.locked"] = ["HUD locked: clicks pass through to the game", "HUD bloqueado: los clics se transmiten al juego", "HUD заблокирован: клики передаются игре", "HUD gesperrt: Klicks gehen an das Spiel", "HUD verrouillé : les clics passent au jeu", "HUD 已锁定：点击将传递到游戏"],
        ["hud.toast.unlocked"] = ["HUD unlocked. Position it with the mouse and lock it again.", "HUD desbloqueado. Colócalo con el ratón y vuelve a bloquearlo.", "HUD разблокирован. Разместите его мышью и снова заблокируйте.", "HUD entsperrt. Mit der Maus positionieren und wieder sperren.", "HUD déverrouillé. Placez-le à la souris puis verrouillez-le.", "HUD 已解锁。用鼠标放置后请重新锁定。"],
        ["hud.toast.key"] = ["Key {0} assigned", "Tecla {0} asignada", "Назначена клавиша {0}", "Taste {0} zugewiesen", "Touche {0} attribuée", "已分配按键 {0}"],
        ["hud.toast.keyBusy"] = ["{0} is in use by another application. Select a different key.", "{0} está en uso por otra aplicación. Selecciona otra tecla.", "{0} используется другим приложением. Выберите другую клавишу.", "{0} wird von einer anderen Anwendung verwendet. Andere Taste wählen.", "{0} est utilisée par une autre application. Choisissez une autre touche.", "{0} 已被其他应用占用。请选择其他按键。"],
        ["lg.hud.on"] = ["HUD: on", "HUD: activado", "HUD: включён", "HUD: an", "HUD : activé", "HUD：已开启"],
        ["lg.hud.off"] = ["HUD: off", "HUD: desactivado", "HUD: выключен", "HUD: aus", "HUD : désactivé", "HUD：已关闭"],
        ["lg.hud.keyBusy"] = ["HUD: key {0} is in use by another application", "HUD: la tecla {0} está en uso por otra aplicación", "HUD: клавиша {0} используется другим приложением", "HUD: Taste {0} wird von einer anderen Anwendung verwendet", "HUD : la touche {0} est utilisée par une autre application", "HUD：按键 {0} 已被其他应用占用"],
        ["hud.unlock.sub"] = ["While unlocked, the HUD receives mouse input. Lock it when finished so that clicks reach the game. It can only be unlocked from here.", "Mientras está desbloqueado, el HUD recibe la entrada del ratón. Bloquéalo al terminar para que los clics lleguen al juego. Solo puede desbloquearse desde aquí.", "В разблокированном состоянии HUD получает ввод мыши. Заблокируйте его по окончании, чтобы клики передавались игре. Разблокировка возможна только здесь.", "Im entsperrten Zustand empfängt das HUD Mauseingaben. Danach wieder sperren, damit Klicks das Spiel erreichen. Entsperren ist nur hier möglich.", "Déverrouillé, le HUD reçoit les entrées de la souris. Verrouillez-le ensuite pour que les clics atteignent le jeu. Le déverrouillage n'est possible qu'ici.", "解锁时，HUD 会接收鼠标输入。完成后请锁定，以便点击传递到游戏。只能在此处解锁。"],

        // ---------- 5.2.0: color en juegos ----------
        ["vib.state.starting"] = ["Active", "Activo", "Активно", "Aktiv", "Actif", "运行中"],
        ["bk.cfg.btn"] = ["Restore RNX settings", "Restaurar configuración de RNX", "Восстановить настройки RNX", "RNX-Einstellungen wiederherstellen", "Restaurer les paramètres RNX", "恢复 RNX 设置"],
        ["bk.cfg.tip"] = ["Each backup also includes the RNX settings (language, colours, custom selection, Digital Vibrance…). Use it on a new computer after connecting Google.", "Cada backup incluye también la configuración de RNX (idioma, colores, selección personalizada, Digital Vibrance…). Utilízalo en un equipo nuevo tras conectar Google.", "Каждый бэкап также содержит настройки RNX (язык, цвета, выборочный набор, Digital Vibrance…). Используйте на новом компьютере после подключения Google.", "Jedes Backup enthält auch die RNX-Einstellungen (Sprache, Farben, benutzerdefinierte Auswahl, Digital Vibrance…). Auf einem neuen Computer nach der Google-Verbindung verwenden.", "Chaque sauvegarde inclut aussi les paramètres RNX (langue, couleurs, sélection personnalisée, Digital Vibrance…). À utiliser sur un nouvel ordinateur après la connexion Google.", "每次备份也会包含 RNX 设置（语言、颜色、自定义选择、Digital Vibrance…）。在新电脑上连接 Google 后使用。"],
        ["bk.cfg.t"] = ["Restore RNX settings from Google Drive?", "¿Restaurar la configuración de RNX desde Google Drive?", "Восстановить настройки RNX с Google Диска?", "RNX-Einstellungen von Google Drive wiederherstellen?", "Restaurer les paramètres RNX depuis Google Drive ?", "从 Google 云端硬盘恢复 RNX 设置？"],
        ["bk.cfg.x"] = ["Language, colours, custom selection, backup options, CS2 font size and Digital Vibrance (including games) will be replaced with those from the latest backup. Computer-specific settings (paths, power plan, scheduled tasks) are not changed.", "El idioma, los colores, la selección personalizada, las opciones de backup, el tamaño de fuente de CS2 y Digital Vibrance (con sus juegos) se sustituirán por los del último backup. No se modifican los ajustes propios del equipo (rutas, plan de energía, tareas programadas).", "Язык, цвета, выборочный набор, параметры бэкапа, размер шрифта CS2 и Digital Vibrance (с играми) будут заменены значениями из последнего бэкапа. Параметры, зависящие от компьютера (пути, схема питания, задания), не изменяются.", "Sprache, Farben, benutzerdefinierte Auswahl, Backup-Optionen, CS2-Schriftgröße und Digital Vibrance (mit Spielen) werden durch die Werte des letzten Backups ersetzt. Computerspezifische Einstellungen (Pfade, Energiesparplan, geplante Aufgaben) bleiben unverändert.", "La langue, les couleurs, la sélection personnalisée, les options de sauvegarde, la taille de police CS2 et Digital Vibrance (avec ses jeux) seront remplacés par ceux de la dernière sauvegarde. Les paramètres propres à l'ordinateur (chemins, mode d'alimentation, tâches planifiées) ne sont pas modifiés.", "语言、颜色、自定义选择、备份选项、CS2 字体大小和 Digital Vibrance（含游戏）将替换为最近一次备份中的设置。与电脑相关的设置（路径、电源计划、计划任务）不会更改。"],
        ["bk.cfg.login"] = ["Connect your Google account first", "Conecta primero la cuenta de Google", "Сначала подключите аккаунт Google", "Zuerst das Google-Konto verbinden", "Connectez d'abord votre compte Google", "请先连接 Google 帐户"],
        ["bk.cfg.none"] = ["No RNX settings found in Google Drive. Run a backup first.", "No hay configuración de RNX en Google Drive. Realiza primero un backup.", "Настройки RNX на Google Диске не найдены. Сначала выполните бэкап.", "Keine RNX-Einstellungen auf Google Drive. Zuerst ein Backup erstellen.", "Aucun paramètre RNX sur Google Drive. Effectuez d'abord une sauvegarde.", "Google 云端硬盘中没有 RNX 设置。请先进行备份。"],
        ["bk.cfg.done"] = ["RNX settings restored", "Configuración de RNX restaurada", "Настройки RNX восстановлены", "RNX-Einstellungen wiederhergestellt", "Paramètres RNX restaurés", "RNX 设置已恢复"],
        ["lg.dr.settingsUp"] = ["DRIVE: RNX settings saved (rnx_settings.json)", "DRIVE: configuración de RNX guardada (rnx_settings.json)", "DRIVE: настройки RNX сохранены (rnx_settings.json)", "DRIVE: RNX-Einstellungen gespeichert (rnx_settings.json)", "DRIVE : paramètres RNX enregistrés (rnx_settings.json)", "云端硬盘：RNX 设置已保存（rnx_settings.json）"],
        ["lg.dr.settingsFail"] = ["DRIVE: RNX settings could not be saved: {0}", "DRIVE: no se ha podido guardar la configuración de RNX: {0}", "DRIVE: не удалось сохранить настройки RNX: {0}", "DRIVE: RNX-Einstellungen konnten nicht gespeichert werden: {0}", "DRIVE : impossible d'enregistrer les paramètres RNX : {0}", "云端硬盘：无法保存 RNX 设置：{0}"],
        ["lg.cfg.restored"] = ["SETTINGS: RNX settings restored from Google Drive", "AJUSTES: configuración de RNX restaurada desde Google Drive", "НАСТРОЙКИ: настройки RNX восстановлены с Google Диска", "EINSTELLUNGEN: RNX-Einstellungen von Google Drive wiederhergestellt", "PARAMÈTRES : paramètres RNX restaurés depuis Google Drive", "设置：已从 Google 云端硬盘恢复 RNX 设置"],
        ["lg.cfg.fail"] = ["SETTINGS: restore error: {0}", "AJUSTES: error al restaurar: {0}", "НАСТРОЙКИ: ошибка восстановления: {0}", "EINSTELLUNGEN: Fehler bei der Wiederherstellung: {0}", "PARAMÈTRES : erreur de restauration : {0}", "设置：恢复出错：{0}"],
        ["nav.vibrance"] = ["Digital Vibrance", "Digital Vibrance", "Digital Vibrance", "Digital Vibrance", "Digital Vibrance", "Digital Vibrance"],
        ["vib.title"] = ["Digital Vibrance", "Digital Vibrance", "Digital Vibrance", "Digital Vibrance", "Digital Vibrance", "Digital Vibrance"],
        ["vib.sub"] = ["Similar to vibranceGUI: increases colour saturation (and optionally changes the resolution) while a listed game is in the foreground, and restores the Windows values on exit. It stays active while RNX is open; when the window is closed, RNX remains in the notification area.", "Similar a vibranceGUI: aumenta la saturación del color (y, opcionalmente, cambia la resolución) mientras un juego de la lista está en primer plano, y restablece los valores de Windows al salir. Permanece activo mientras RNX esté abierto; al cerrar la ventana, RNX continúa en el área de notificación.", "Аналог vibranceGUI: повышает насыщенность цвета (и при необходимости меняет разрешение), пока игра из списка на переднем плане, и восстанавливает значения Windows при выходе. Работает, пока RNX открыт; при закрытии окна RNX остаётся в области уведомлений.", "Ähnlich wie vibranceGUI: erhöht die Farbsättigung (und ändert optional die Auflösung), solange ein Spiel aus der Liste im Vordergrund ist, und stellt beim Verlassen die Windows-Werte wieder her. Bleibt aktiv, solange RNX geöffnet ist; beim Schließen des Fensters bleibt RNX im Infobereich.", "Similaire à vibranceGUI : augmente la saturation des couleurs (et change éventuellement la résolution) lorsqu'un jeu de la liste est au premier plan, puis rétablit les valeurs de Windows à la sortie. Reste actif tant que RNX est ouvert ; à la fermeture de la fenêtre, RNX reste dans la zone de notification.", "类似 vibranceGUI：当列表中的游戏位于前台时提高色彩饱和度（并可更改分辨率），退出时恢复 Windows 设置。RNX 打开期间始终生效；关闭窗口后 RNX 会保留在通知区域。"],
        ["vib.nogpu"] = ["Requires an NVIDIA or AMD graphics card.", "Requiere una tarjeta gráfica NVIDIA o AMD.", "Требуется видеокарта NVIDIA или AMD.", "Erfordert eine NVIDIA- oder AMD-Grafikkarte.", "Nécessite une carte graphique NVIDIA ou AMD.", "需要 NVIDIA 或 AMD 显卡。"],
        ["vib.state.off"] = ["Disabled", "Desactivado", "Отключено", "Deaktiviert", "Désactivé", "已禁用"],
        ["vib.state.on"] = ["Active · waiting for a listed game", "Activo · en espera de un juego de la lista", "Активно · ожидание игры из списка", "Aktiv · wartet auf ein Spiel aus der Liste", "Actif · en attente d'un jeu de la liste", "已启用 · 等待列表中的游戏"],
        ["vib.state.game"] = ["Active · {0} in the foreground", "Activo · {0} en primer plano", "Активно · {0} на переднем плане", "Aktiv · {0} im Vordergrund", "Actif · {0} au premier plan", "已启用 · {0} 位于前台"],
        ["vib.state.error"] = ["Could not be started. See the Log.", "No se ha podido iniciar. Consulta el Registro.", "Не удалось запустить. См. журнал.", "Konnte nicht gestartet werden. Siehe Protokoll.", "Démarrage impossible. Consultez le Journal.", "无法启动。请查看日志。"],
        ["vib.gpu"] = ["Graphics card: {0}", "Gráfica: {0}", "Видеокарта: {0}", "Grafikkarte: {0}", "Carte graphique : {0}", "显卡：{0}"],
        ["vib.other"] = ["vibranceGUI is running. Two applications changing colour at the same time conflict with each other; close it (you can import its games first).", "vibranceGUI está en ejecución. Dos aplicaciones modificando el color simultáneamente generan conflictos; ciérralo (puedes importar antes sus juegos).", "vibranceGUI запущен. Два приложения, одновременно меняющие цвет, конфликтуют; закройте его (сначала можно импортировать его игры).", "vibranceGUI läuft. Zwei Anwendungen, die gleichzeitig die Farbe ändern, stören sich gegenseitig; bitte schließen (Spiele können vorher importiert werden).", "vibranceGUI est en cours d'exécution. Deux applications modifiant la couleur simultanément entrent en conflit ; fermez-le (vous pouvez d'abord importer ses jeux).", "vibranceGUI 正在运行。两个应用同时修改色彩会互相冲突，请将其关闭（可先导入其游戏）。"],
        ["vib.other.btn"] = ["Close vibranceGUI", "Cerrar vibranceGUI", "Закрыть vibranceGUI", "vibranceGUI schließen", "Fermer vibranceGUI", "关闭 vibranceGUI"],
        ["vib.default"] = ["Windows color", "Color de Windows", "Цвет Windows", "Windows-Farbe", "Couleur de Windows", "Windows 色彩"],
        ["vib.default.h"] = ["Level outside games. Default: 50 % (NVIDIA) or 100 % (AMD).", "Nivel fuera de los juegos. Valor predeterminado: 50 % (NVIDIA) o 100 % (AMD).", "Уровень вне игр. По умолчанию: 50 % (NVIDIA) или 100 % (AMD).", "Wert außerhalb von Spielen. Standard: 50 % (NVIDIA) oder 100 % (AMD).", "Niveau hors jeux. Par défaut : 50 % (NVIDIA) ou 100 % (AMD).", "游戏外的级别。默认：50%（NVIDIA）或 100%（AMD）。"],
        ["vib.primary"] = ["Main monitor only", "Solo el monitor principal", "Только основной монитор", "Nur Hauptmonitor", "Écran principal uniquement", "仅主显示器"],
        ["vib.primary.h"] = ["When off, it applies to all monitors.", "Desactivado: se aplica a todos los monitores.", "Если выключено, применяется ко всем мониторам.", "Deaktiviert: gilt für alle Monitore.", "Désactivé : s'applique à tous les écrans.", "关闭时应用于所有显示器。"],
