        ["vib.toast.exists"] = ["{0} is already in the list", "{0} ya está en la lista", "{0} уже в списке", "{0} ist schon in der Liste", "{0} est déjà dans la liste", "{0} 已在列表中"],
        ["vib.toast.noprocs"] = ["No running programs with a window", "No hay programas en ejecución con ventana", "Нет запущенных программ с окном", "Keine laufenden Programme mit Fenster", "Aucun programme ouvert avec fenêtre", "没有带窗口的运行程序"],
