        ["lg.vib.started"] = ["VIBRANCE: watcher started ({0})", "VIBRANCE: observador iniciado ({0})", "VIBRANCE: наблюдение запущено ({0})", "VIBRANCE: Überwachung gestartet ({0})", "VIBRANCE : surveillance démarrée ({0})", "VIBRANCE：监视已启动（{0}）"],
