        // ---------- 5.2.0: video CS2 ----------
        ["nav.sub.modules"] = ["Modules", "Módulos", "Модули", "Module", "Modules", "模块"],
        ["nav.sub.video"] = ["Video", "Vídeo", "Видео", "Grafik", "Vidéo", "画面"],
        ["nav.sub.fonts"] = ["Fonts", "Fuentes", "Шрифты", "Schriften", "Polices", "字体"],
        ["nav.customres"] = ["Custom Resolution", "Custom Resolution", "Custom Resolution", "Custom Resolution", "Custom Resolution", "Custom Resolution"],
        ["res.list"] = ["Graphics driver resolutions", "Resoluciones del controlador gráfico", "Разрешения графического драйвера", "Auflösungen des Grafiktreibers", "Résolutions du pilote graphique", "显卡驱动分辨率"],
        ["res.title"] = ["Custom Resolution", "Custom Resolution", "Custom Resolution", "Custom Resolution", "Custom Resolution", "Custom Resolution"],
        ["res.sub"] = ["Resolutions available on {0}, scaled by the GPU. Add custom resolutions (e.g. 1352×1080 stretched) and restart the computer so that Windows and CS2 can use them.", "Resoluciones disponibles en {0}, escaladas por la GPU. Añade resoluciones personalizadas (p. ej., 1352×1080 estirada) y reinicia el equipo para que Windows y CS2 puedan utilizarlas.", "Разрешения, доступные на {0}, масштабируются GPU. Добавьте собственные разрешения (например, 1352×1080 растянутое) и перезагрузите компьютер, чтобы Windows и CS2 могли их использовать.", "Auf {0} verfügbare Auflösungen, von der GPU skaliert. Eigene Auflösungen hinzufügen (z. B. 1352×1080 gestreckt) und den Computer neu starten, damit Windows und CS2 sie nutzen können.", "Résolutions disponibles sur {0}, mises à l'échelle par le GPU. Ajoutez des résolutions personnalisées (p. ex. 1352×1080 étirée) et redémarrez l'ordinateur pour que Windows et CS2 puissent les utiliser.", "{0} 上可用的分辨率，由 GPU 缩放。添加自定义分辨率（例如 1352×1080 拉伸）后重启电脑，Windows 和 CS2 即可使用。"],
        ["res.nogpu"] = ["Requires an NVIDIA or AMD graphics card.", "Requiere una tarjeta gráfica NVIDIA o AMD.", "Требуется видеокарта NVIDIA или AMD.", "Erfordert eine NVIDIA- oder AMD-Grafikkarte.", "Nécessite une carte graphique NVIDIA ou AMD.", "需要 NVIDIA 或 AMD 显卡。"],
        ["res.add"] = ["Add", "Añadir", "Добавить", "Hinzufügen", "Ajouter", "添加"],
        ["res.remove"] = ["Remove", "Quitar", "Удалить", "Entfernen", "Supprimer", "移除"],
        ["res.restore"] = ["Restore defaults", "Restablecer predeterminadas", "Сбросить по умолчанию", "Standard wiederherstellen", "Rétablir par défaut", "恢复默认"],
        ["res.restore.t"] = ["Restore the default resolutions?", "¿Restablecer las resoluciones predeterminadas?", "Восстановить разрешения по умолчанию?", "Standardauflösungen wiederherstellen?", "Rétablir les résolutions par défaut ?", "恢复默认分辨率？"],
        ["res.restore.x"] = ["All custom resolutions, including those added with other tools, will be removed and the graphics driver's default list will be restored. A restart is required afterwards.", "Se eliminarán todas las resoluciones personalizadas, incluidas las añadidas con otras herramientas, y se restablecerá la lista predeterminada del controlador gráfico. Después es necesario reiniciar.", "Все пользовательские разрешения, включая добавленные другими программами, будут удалены, и будет восстановлен список драйвера по умолчанию. Затем потребуется перезагрузка.", "Alle benutzerdefinierten Auflösungen, auch die mit anderen Tools hinzugefügten, werden entfernt und die Standardliste des Grafiktreibers wird wiederhergestellt. Anschließend ist ein Neustart erforderlich.", "Toutes les résolutions personnalisées, y compris celles ajoutées avec d'autres outils, seront supprimées et la liste par défaut du pilote graphique sera rétablie. Un redémarrage est ensuite nécessaire.", "将删除所有自定义分辨率（包括通过其他工具添加的），并恢复显卡驱动的默认列表。之后需要重启。"],
        ["res.reboot"] = ["A restart is required for the changes to appear in Windows and CS2. We recommend restarting now.", "Es necesario reiniciar para que los cambios aparezcan en Windows y en CS2. Se recomienda reiniciar ahora.", "Чтобы изменения появились в Windows и CS2, нужна перезагрузка. Рекомендуется перезагрузить сейчас.", "Ein Neustart ist erforderlich, damit die Änderungen in Windows und CS2 erscheinen. Wir empfehlen, jetzt neu zu starten.", "Un redémarrage est nécessaire pour que les changements apparaissent dans Windows et CS2. Nous recommandons de redémarrer maintenant.", "需要重启才能在 Windows 和 CS2 中看到更改。建议立即重启。"],
        ["res.reboot.btn"] = ["Restart now", "Reiniciar ahora", "Перезагрузить", "Jetzt neu starten", "Redémarrer", "立即重启"],
        ["res.toast"] = ["Saved. Restart required to apply", "Guardado. Es necesario reiniciar para aplicarlo", "Сохранено. Требуется перезагрузка", "Gespeichert. Neustart erforderlich", "Enregistré. Redémarrage nécessaire", "已保存，需要重启后生效"],
        ["res.invalid"] = ["Enter a width and height between {0} and {1}", "Introduce un ancho y un alto entre {0} y {1}", "Введите ширину и высоту от {0} до {1}", "Breite und Höhe zwischen {0} und {1} eingeben", "Saisissez une largeur et une hauteur entre {0} et {1}", "请输入 {0} 到 {1} 之间的宽度和高度"],
        ["lg.res.added"] = ["RESOLUTION: {0} added to {1} (restart required)", "RESOLUCIÓN: {0} añadida a {1} (requiere reinicio)", "РАЗРЕШЕНИЕ: {0} добавлено для {1} (требуется перезагрузка)", "AUFLÖSUNG: {0} zu {1} hinzugefügt (Neustart erforderlich)", "RÉSOLUTION : {0} ajoutée à {1} (redémarrage requis)", "分辨率：已向 {1} 添加 {0}（需要重启）"],
        ["lg.res.removed"] = ["RESOLUTION: {0} removed from {1} (restart required)", "RESOLUCIÓN: {0} eliminada de {1} (requiere reinicio)", "РАЗРЕШЕНИЕ: {0} удалено для {1} (требуется перезагрузка)", "AUFLÖSUNG: {0} von {1} entfernt (Neustart erforderlich)", "RÉSOLUTION : {0} supprimée de {1} (redémarrage requis)", "分辨率：已从 {1} 移除 {0}（需要重启）"],
        ["lg.res.restored"] = ["RESOLUTION: {0} restored to the default list", "RESOLUCIÓN: {0} restablecida a la lista predeterminada", "РАЗРЕШЕНИЕ: для {0} восстановлен список по умолчанию", "AUFLÖSUNG: {0} auf Standardliste zurückgesetzt", "RÉSOLUTION : {0} rétabli à la liste par défaut", "分辨率：{0} 已恢复默认列表"],
        ["lg.res.fail"] = ["RESOLUTION: error: {0}", "RESOLUCIÓN: error: {0}", "РАЗРЕШЕНИЕ: ошибка: {0}", "AUFLÖSUNG: Fehler: {0}", "RÉSOLUTION : erreur : {0}", "分辨率：错误：{0}"],
        ["vid.rnx.title"] = ["RNX full CS2 configuration", "Configuración completa de CS2 de RNX", "Полная конфигурация CS2 от RNX", "Vollständige CS2-Konfiguration von RNX", "Configuration CS2 complète de RNX", "RNX 完整 CS2 配置"],
        ["vid.rnx.sub"] = ["Applies Ren0X1's binds, sensitivity, crosshair, game options and video settings to this account. The in-game name is kept, and the current configuration is saved so it can be restored.", "Aplica a esta cuenta los binds, la sensibilidad, la mira, las opciones de juego y el vídeo de Ren0X1. Se conserva el nombre en el juego y la configuración actual se guarda para poder restaurarla.", "Применяет к этому аккаунту бинды, чувствительность, прицел, игровые параметры и видео Ren0X1. Игровое имя сохраняется, текущая конфигурация сохраняется для восстановления.", "Überträgt Binds, Empfindlichkeit, Fadenkreuz, Spieloptionen und Videoeinstellungen von Ren0X1 auf dieses Konto. Der Spielname bleibt erhalten, und die aktuelle Konfiguration wird zur Wiederherstellung gesichert.", "Applique à ce compte les binds, la sensibilité, le viseur, les options de jeu et les paramètres vidéo de Ren0X1. Le pseudo en jeu est conservé et la configuration actuelle est enregistrée pour pouvoir la restaurer.", "将 Ren0X1 的按键绑定、灵敏度、准星、游戏选项和视频设置应用到此帐户。保留游戏内名称，并保存当前配置以便恢复。"],
        ["vid.rnx.btn"] = ["Apply RNX configuration", "Aplicar configuración de RNX", "Применить конфигурацию RNX", "RNX-Konfiguration anwenden", "Appliquer la configuration RNX", "应用 RNX 配置"],
        ["vid.rnx.restore"] = ["Restore my config", "Restaurar mi configuración", "Восстановить мой конфиг", "Meine Konfig wiederherstellen", "Restaurer ma configuration", "恢复我的配置"],
        ["vid.rnx.dlg.t"] = ["Apply the RNX configuration to {0}?", "¿Aplicar la configuración de RNX a {0}?", "Применить конфигурацию RNX к {0}?", "RNX-Konfiguration auf {0} anwenden?", "Appliquer la configuration RNX à {0} ?", "将 RNX 配置应用到 {0}？"],
        ["vid.rnx.dlg.x"] = ["Binds, sensitivity, crosshair, options and video settings will be replaced with those of RNX. The current configuration is saved first and can be recovered with \"Restore my configuration\". If Steam reports a cloud sync conflict when opening CS2, select the files on this computer.", "Los binds, la sensibilidad, la mira, las opciones y el vídeo se sustituirán por los de RNX. La configuración actual se guarda antes y puede recuperarse con \"Restaurar mi configuración\". Si Steam indica un conflicto de sincronización en la nube al abrir CS2, selecciona los archivos de este equipo.", "Бинды, чувствительность, прицел, параметры и видео будут заменены настройками RNX. Текущая конфигурация предварительно сохраняется и восстанавливается кнопкой «Восстановить мою конфигурацию». Если при запуске CS2 Steam сообщит о конфликте облачной синхронизации, выберите файлы этого компьютера.", "Binds, Empfindlichkeit, Fadenkreuz, Optionen und Videoeinstellungen werden durch die von RNX ersetzt. Die aktuelle Konfiguration wird vorher gesichert und kann mit „Meine Konfiguration wiederherstellen“ zurückgeholt werden. Meldet Steam beim Start von CS2 einen Cloud-Synchronisierungskonflikt, die Dateien dieses Computers wählen.", "Les binds, la sensibilité, le viseur, les options et les paramètres vidéo seront remplacés par ceux de RNX. La configuration actuelle est enregistrée au préalable et peut être récupérée avec « Restaurer ma configuration ». Si Steam signale un conflit de synchronisation cloud au lancement de CS2, choisissez les fichiers de cet ordinateur.", "按键绑定、灵敏度、准星、选项和视频设置将替换为 RNX 的设置。当前配置会先行保存，可通过“恢复我的配置”找回。若启动 CS2 时 Steam 提示云同步冲突，请选择本机文件。"],
        ["vid.rnx.cs2"] = ["CS2 must be closed to change its configuration; otherwise it would overwrite it on exit. Close CS2 and continue?", "CS2 debe estar cerrado para modificar su configuración; de lo contrario, la sobrescribiría al salir. ¿Cerrar CS2 y continuar?", "Для изменения конфигурации CS2 должен быть закрыт, иначе он перезапишет её при выходе. Закрыть CS2 и продолжить?", "CS2 muss geschlossen sein, um die Konfiguration zu ändern, sonst wird sie beim Beenden überschrieben. CS2 schließen und fortfahren?", "CS2 doit être fermé pour modifier sa configuration, sinon il l'écraserait à la fermeture. Fermer CS2 et continuer ?", "修改配置前必须关闭 CS2，否则退出时会被覆盖。关闭 CS2 并继续？"],
        ["vid.rnx.toast"] = ["RNX configuration applied", "Configuración de RNX aplicada", "Конфигурация RNX применена", "RNX-Konfiguration angewendet", "Configuration RNX appliquée", "已应用 RNX 配置"],
        ["vid.rnx.restore.t"] = ["Restore the previous configuration of {0}?", "¿Restaurar la configuración anterior de {0}?", "Восстановить прежнюю конфигурацию {0}?", "Vorherige Konfiguration von {0} wiederherstellen?", "Restaurer la configuration précédente de {0} ?", "恢复 {0} 之前的配置？"],
        ["vid.rnx.restore.x"] = ["Restores the binds, sensitivity, crosshair, options and video settings this account had before the RNX configuration was applied.", "Restaura los binds, la sensibilidad, la mira, las opciones y el vídeo que tenía esta cuenta antes de aplicar la configuración de RNX.", "Восстанавливает бинды, чувствительность, прицел, параметры и видео, которые были у аккаунта до применения конфигурации RNX.", "Stellt Binds, Empfindlichkeit, Fadenkreuz, Optionen und Videoeinstellungen wieder her, die das Konto vor der RNX-Konfiguration hatte.", "Rétablit les binds, la sensibilité, le viseur, les options et les paramètres vidéo du compte avant l'application de la configuration RNX.", "恢复此帐户应用 RNX 配置之前的按键绑定、灵敏度、准星、选项和视频设置。"],
        ["vid.rnx.restored"] = ["Previous configuration restored", "Configuración anterior restaurada", "Прежняя конфигурация восстановлена", "Vorherige Konfiguration wiederhergestellt", "Configuration précédente restaurée", "已恢复之前的配置"],
        ["lg.vid.rnx"] = ["CS2 CONFIG: RNX configuration applied to {0} ({1} files; previous configuration saved)", "CONFIG CS2: configuración de RNX aplicada a {0} ({1} archivos; la anterior se ha guardado)", "КОНФИГ CS2: конфигурация RNX применена к {0} ({1} файлов; прежняя сохранена)", "CS2-KONFIG: RNX-Konfiguration auf {0} angewendet ({1} Dateien; vorherige gesichert)", "CONFIG CS2 : configuration RNX appliquée à {0} ({1} fichiers ; précédente enregistrée)", "CS2 配置：已将 RNX 配置应用到 {0}（{1} 个文件，已保存之前的配置）"],
        ["lg.vid.rnxRestored"] = ["CS2 CONFIG: previous configuration of {0} restored ({1} files)", "CONFIG CS2: configuración anterior de {0} restaurada ({1} archivos)", "КОНФИГ CS2: прежняя конфигурация {0} восстановлена ({1} файлов)", "CS2-KONFIG: vorherige Konfiguration von {0} wiederhergestellt ({1} Dateien)", "CONFIG CS2 : configuration précédente de {0} restaurée ({1} fichiers)", "CS2 配置：已恢复 {0} 之前的配置（{1} 个文件）"],
        ["nav.video"] = ["CS2 video", "Vídeo CS2", "Видео CS2", "CS2-Grafik", "Vidéo CS2", "CS2 画面"],
        ["vid.title"] = ["CS2 video settings", "Ajustes de vídeo de CS2", "Настройки видео CS2", "CS2-Grafikeinstellungen", "Réglages vidéo de CS2", "CS2 画面设置"],
        ["vid.sub"] = ["Configure CS2 graphics without opening the game and lock them to prevent changes.", "Configura los gráficos de CS2 sin abrir el juego y bloquéalos para evitar que se modifiquen.", "Настройте графику CS2 без запуска игры и заблокируйте её от изменений.", "CS2-Grafik ohne Spielstart konfigurieren und gegen Änderungen sperren.", "Configurez les graphismes de CS2 sans lancer le jeu et verrouillez-les pour éviter toute modification.", "无需打开游戏即可配置 CS2 图形设置，并可锁定以防被更改。"],
        ["vid.none"] = ["CS2 video settings were not found. Start CS2 once to generate them.", "No se ha encontrado la configuración de vídeo de CS2. Inicia CS2 una vez para generarla.", "Видеонастройки CS2 не найдены. Запустите CS2 один раз, чтобы создать их.", "CS2-Videoeinstellungen nicht gefunden. CS2 einmal starten, um sie zu erzeugen.", "Paramètres vidéo de CS2 introuvables. Lancez CS2 une fois pour les générer.", "未找到 CS2 视频设置。请启动一次 CS2 以生成设置。"],
        ["vid.cs2open"] = ["CS2 is running: changes will apply the next time it starts. If the settings are not locked, CS2 will overwrite them when it closes.", "CS2 está en ejecución: los cambios se aplicarán en el próximo inicio. Si la configuración no está bloqueada, CS2 la sobrescribirá al cerrarse.", "CS2 запущен: изменения вступят в силу при следующем запуске. Если настройки не заблокированы, CS2 перезапишет их при закрытии.", "CS2 läuft: Änderungen gelten beim nächsten Start. Sind die Einstellungen nicht gesperrt, überschreibt CS2 sie beim Beenden.", "CS2 est en cours d'exécution : les modifications s'appliqueront au prochain lancement. Si les paramètres ne sont pas verrouillés, CS2 les écrasera à la fermeture.", "CS2 正在运行：更改将在下次启动时生效。如未锁定设置，CS2 关闭时会将其覆盖。"],
        ["vid.lock.on.t"] = ["Locked: CS2 cannot change these settings", "Bloqueado: CS2 no puede modificar esta configuración", "Заблокировано: CS2 не может изменить эти настройки", "Gesperrt: CS2 kann diese Einstellungen nicht ändern", "Verrouillé : CS2 ne peut pas modifier ces paramètres", "已锁定：CS2 无法更改这些设置"],
        ["vid.lock.on.x"] = ["Turn off the lock to edit them here. While locked, changes made in game are not saved.", "Desactiva el bloqueo para editarla aquí. Mientras esté activo, los cambios realizados en el juego no se guardan.", "Отключите блокировку, чтобы редактировать их здесь. Пока она включена, изменения в игре не сохраняются.", "Sperre deaktivieren, um sie hier zu bearbeiten. Solange sie aktiv ist, werden Änderungen im Spiel nicht gespeichert.", "Désactivez le verrouillage pour les modifier ici. Tant qu'il est actif, les modifications faites en jeu ne sont pas enregistrées.", "关闭锁定后可在此编辑。锁定期间，游戏内的更改不会保存。"],
        ["vid.lock.off.t"] = ["Unlocked: editing enabled", "Desbloqueado: edición habilitada", "Разблокировано: редактирование доступно", "Entsperrt: Bearbeitung möglich", "Déverrouillé : modification activée", "已解锁：可以编辑"],
        ["vid.lock.off.x"] = ["Changes are saved immediately. Turn on the lock when finished so that CS2 cannot change them.", "Los cambios se guardan al instante. Activa el bloqueo al terminar para que CS2 no la modifique.", "Изменения сохраняются сразу. По окончании включите блокировку, чтобы CS2 их не менял.", "Änderungen werden sofort gespeichert. Danach die Sperre aktivieren, damit CS2 sie nicht ändert.", "Les modifications sont enregistrées immédiatement. Activez le verrouillage ensuite pour que CS2 ne les modifie pas.", "更改会立即保存。完成后请开启锁定，防止 CS2 更改。"],
        ["vid.presets"] = ["Presets", "Perfiles", "Предустановки", "Voreinstellungen", "Préréglages", "预设"],
        ["vid.preset.fps"] = ["Maximum FPS", "Máximo rendimiento", "Максимум FPS", "Maximale FPS", "FPS maximum", "最高帧率"],
        ["vid.preset.fps.d"] = ["Low detail and a clean image. The usual competitive setup.", "Detalle bajo e imagen nítida. Configuración habitual en competitivo.", "Низкая детализация и чистое изображение. Типичная соревновательная настройка.", "Geringe Details und klares Bild. Übliche Wettkampfeinstellung.", "Détails faibles et image nette. Configuration compétitive habituelle.", "低细节、画面清晰。常见的竞技设置。"],
        ["vid.preset.balanced"] = ["Balanced", "Equilibrado", "Баланс", "Ausgewogen", "Équilibré", "平衡"],
